    ["Backdrop"] = "배경화면",
    ["Blizzard draws these icons on MSUF's frame container. If icons appear behind frames, adjust the advanced layering controls."] = "Blizzard는 MSUF의 프레임 컨테이너에 이러한 아이콘을 그립니다. 프레임 뒤에 아이콘이 나타나면 고급 레이어링 컨트롤을 조정하세요.",
    ["Blizzard mode lets WoW place the selected aura types. MSUF Custom mode lets MSUF control aura size, growth, position, filters, and styling. MSUF Dispel Border / Glow keeps Blizzard icons while allowing MSUF's dispel highlight visuals."] = "Blizzard 모드를 사용하면 WoW가 선택한 오라 유형을 배치할 수 있습니다. MSUF 사용자 정의 모드를 사용하면 MSUF가 오라 크기, 성장, 위치, 필터 및 스타일을 제어할 수 있습니다. MSUF Dispel Border / Glow는 Blizzard 아이콘을 유지하면서 MSUF의 dispel 하이라이트 시각적 효과를 허용합니다.",
    ["Boss frames normally appear only during boss encounters. Enable Boss Frames and use Edit Mode or Boss Preview to test them outside combat."] = "보스 프레임은 일반적으로 보스와의 만남 중에만 나타납니다. 보스 프레임을 활성화하고 편집 모드나 보스 미리보기를 사용하여 전투 밖에서 테스트해보세요.",
