    ["Confirm stages the reset; reload via /reload or MSUF Menu > Advanced > Factory Reset."] = "재설정 단계를 확인하세요. /reload 또는 MSUF 메뉴 > 고급 > 공장 재설정을 통해 다시 로드합니다.",
