    ["Edit"] = "편집",
    ["For bar backgrounds: Bar Background Tint. White in Dark Mode needs Custom color in Dark Mode; black track? check Preserve HP color."] = "막대 배경의 경우: 막대 배경 색조. 다크 모드의 흰색은 다크 모드에서 사용자 정의 색상이 필요합니다. 검은 트랙? HP 색상 유지를 확인하세요.",
