    ["Global Style > Fonts controls shared font settings. Unit pages contain per-unit name, health, and power text position and pattern settings."] = "전역 스타일 > 글꼴은 공유 글꼴 설정을 제어합니다. 유닛 페이지에는 유닛별 이름, 체력, 전원 텍스트 위치 및 패턴 설정이 포함되어 있습니다.",
    ["Global Style > Fonts has Shared settings plus per-scope font overrides. If Party or Raid uses custom font settings, its Name Shortening can stay enabled even when Shared is off. Select Party/Raid in Fonts or reset the font override."] = "전역 스타일 > 글꼴에는 공유 설정과 범위별 글꼴 재정의가 있습니다. Party 또는 Raid가 사용자 정의 글꼴 설정을 사용하는 경우 공유가 꺼진 경우에도 이름 단축이 활성화된 상태로 유지될 수 있습니다. 글꼴에서 Party/Raid를 선택하거나 글꼴 재정의를 재설정하세요.",
