    ["Opens: Global Style > Fonts > Name Shortening / scope override"] = "열림: 전역 스타일 > 글꼴 > 이름 단축/범위 재정의",
    ["Opens: Global Style > Miscellaneous"] = "열림: 글로벌 스타일 > 기타",
    ["Opens: Global Style > Miscellaneous > Blizzard Frames"] = "열림: 글로벌 스타일 > 기타 > Blizzard 프레임",
