    ["Opens: Global Style > Miscellaneous > Unitframe tooltips"] = "열림: 전역 스타일 > 기타 > 유닛프레임 툴팁",
    ["Opens: Global Style > Unit Auras"] = "열림: 글로벌 스타일 > 유닛 오라",
