    ["Opens: Group Frames > Buffs & Debuffs > Aura Utilities"] = "열림: 그룹 프레임 > 버프 및 디버프 > Aura 유틸리티",
    ["Opens: Group Frames > Buffs & Debuffs > Buffs"] = "열림: 그룹 프레임 > 버프 및 디버프 > 버프",
    ["Opens: Group Frames > Health & Text"] = "열림: 그룹 프레임 > 건강 및 텍스트",
    ["Opens: Group Frames > Health & Text > Range Fade"] = "열림: 그룹 프레임 > 건강 및 텍스트 > 범위 페이드",
    ["Opens: Group Frames > Indicators"] = "열림: 그룹 프레임 > 표시기",
    ["Opens: Group Frames > Indicators > Dispel / Status Icons"] = "열림: 그룹 프레임 > 표시기 > 해제/상태 아이콘",
