L["Preserve HP color keeps the HP fill color while layer fade is active and draws missing health separately with the same HP track color from Colors.\n\nThis can help when HP Bar fade makes the empty HP area disappear or look black. Some custom textures may still look flat, dark, or different while this option is enabled."] = "HP 색상 유지는 레이어 페이드가 활성화된 동안 HP 채우기 색상을 유지하고, 색상 설정의 동일한 HP 트랙 색상으로 잃은 생명력을 별도로 그립니다.\n\nHP 바 페이드로 빈 HP 영역이 사라지거나 검게 보일 때 도움이 됩니다. 일부 사용자 텍스처는 이 옵션을 켜도 평평하거나 어둡거나 다르게 보일 수 있습니다."
L["Reset %s to defaults?\n\nThis resets %s for the active profile. Defaults are read from the current MSUF factory profile, so future default changes are used automatically."] = "%s을(를) 기본값으로 재설정할까요?\n\n활성 프로필의 %s을(를) 재설정합니다. 기본값은 현재 MSUF 공장 프로필에서 읽으므로 향후 기본값 변경도 자동으로 사용됩니다."
L["Reset %s to defaults?\n\nThis resets the entire active profile '%s' to the current MSUF factory defaults. Every menu in that profile will be affected."] = "%s을(를) 기본값으로 재설정할까요?\n\n활성 프로필 '%s' 전체를 현재 MSUF 공장 기본값으로 재설정합니다. 이 프로필의 모든 메뉴가 영향을 받습니다."
L["Reset Scopes"] = "범위 재설정"

