L["|cffffcc00MSUF:|r Then click: MSUF Menu > Advanced > Factory Reset (or type /reload)."] = "|cffffcc00MSUF:|r 그런 다음 MSUF 메뉴 > 고급 > 공장 초기화를 클릭하세요(또는 /reload 입력)."
