L["|cffffff00MSUF:|r Reset staged. Please type |cff00ff00/reload|r OR use: MSUF Menu > Advanced > Factory Reset."] = "|cffffff00MSUF:|r 초기화가 준비되었습니다. |cff00ff00/reload|r를 입력하거나 MSUF 메뉴 > 고급 > 공장 초기화를 사용하세요."
