L["A %s in your group can provide this."] = "파티/공격대의 %s|1이;가; 이를 제공할 수 있습니다."
L["A calmer setup command center: start with movement, frames, group frames, or a safe profile import."] = "더 차분한 설정 허브입니다. 위치 이동, 프레임, 파티/공격대 프레임 또는 안전한 프로필 가져오기부터 시작하세요."
L["Active Spell Indicators:"] = "활성 주문 표시기:"
L["Add menu scroll edge bounce."] = "메뉴 스크롤 가장자리 bounce를 추가했습니다."
L["Add Spell..."] = "주문 추가..."
L["Added and refined the Menu2 search module."] = "Menu2 검색 모듈을 추가하고 다듬었습니다."
L["Added backend compatibility hardening across MSUF modules."] = "MSUF 모듈 전반의 backend 호환성 보강을 추가했습니다."
L["Added centralized font registry support for the unit frame runtime."] = "유닛 프레임 runtime을 위한 중앙 글꼴 등록 지원을 추가했습니다."
L["Added class-colored bar background support across unit and group frames."] = "유닛 및 그룹 프레임에 직업 색상 바 배경 지원을 추가했습니다."
L["Added core swap recolor runtime support."] = "core swap recolor runtime 지원을 추가했습니다."
L["Added Focus Target frame support across unit settings, edit mode, menu previews, copy targets, text options, icons, and runtime refreshes."] = "유닛 설정, 편집 모드, 메뉴 미리보기, 복사 대상, 텍스트 옵션, 아이콘, runtime 갱신에 주시 대상 프레임 지원을 추가했습니다."
L["Added improved on/off switch visuals."] = "개선된 켜기/끄기 스위치 시각 효과를 추가했습니다."
L["Added more Menu2 cards and refined menu structure."] = "Menu2 카드를 더 추가하고 메뉴 구조를 다듬었습니다."
L["Added more Menu2 cards to group and unit sections."] = "그룹 및 유닛 섹션에 Menu2 카드를 더 추가했습니다."
L["Added new Menu2 search module and improved search/guidance text."] = "새 Menu2 검색 모듈을 추가하고 검색/안내 텍스트를 개선했습니다."
L["Added new UI/media assets for switches and rounded/superellipse visuals."] = "스위치와 둥근/superellipse 시각 효과용 새 UI/미디어 애셋을 추가했습니다."
L["Added raid group number display next to unit names."] = "유닛 이름 옆에 공격대 그룹 번호 표시를 추가했습니다."
L["Added redesigned Menu2 card layout across unit, group, aura, indicator, bar, and advanced pages."] = "유닛, 그룹, 오라, 표시기, 바, 고급 페이지에 재디자인된 Menu2 카드 레이아웃을 추가했습니다."
L["Added Rounded Frames with per-surface controls for unit frames, group frames, bars, highlights, overlays, absorbs, and indicators."] = "유닛 프레임, 그룹 프레임, 바, 강조, 오버레이, 흡수, 표시기에 표면별 제어가 있는 둥근 프레임을 추가했습니다."
L["Added rounded mask media for the live unit/group frames and Menu2 preview."] = "실제 유닛/그룹 프레임과 Menu2 미리보기에 둥근 마스크 미디어를 추가했습니다."
L["Added Rounded Texture controls under Global Style > Bars with per-surface toggles, search coverage, localization, preview support, and a reload prompt."] = "전역 스타일 > 바 아래에 표면별 토글, 검색, 지역화, 미리보기, 재시작 안내를 포함한 둥근 텍스처 컨트롤을 추가했습니다."
