L["BG"] = "배경"
L["Blizzard controls this aura block, so MSUF cannot drag it. Switch to MSUF Custom mode if you want full positioning control. The preview marks the Blizzard-owned area."] = "Blizzard가 이 오라 블록을 제어하므로 MSUF는 끌 수 없습니다. 위치를 완전히 제어하려면 MSUF 사용자 지정 모드로 전환하세요. 미리보기는 Blizzard 소유 영역을 표시합니다."
L["Blizzard locked"] = "블리자드 잠금"
L["Blizzard mode lets WoW place the selected aura types. MSUF Custom mode lets MSUF control aura size, growth, position, filters, and styling. Dispel Glow is unavailable only for Group Frame scopes where Blizzard controls the aura layer."] = "Blizzard 모드는 WoW가 선택한 오라 유형을 배치하게 합니다. MSUF 사용자 지정 모드는 MSUF가 오라 크기, 성장, 위치, 필터, 스타일을 제어합니다. 해제 광채는 Blizzard가 오라 레이어를 제어하는 그룹 프레임 범위에서만 사용할 수 없습니다."
L["Blizzard renders cooldown/stack text for native Buffs and Debuffs. These text overlay fields only affect custom icons."] = "기본 버프와 디버프의 재사용 대기시간/중첩 글자는 블리자드가 표시합니다. 이 텍스트 오버레이 항목은 사용자 지정 아이콘에만 적용됩니다."
L["Blizzard TotemFrame Preview"] = "블리자드 토템 프레임 미리보기"
