L["Delete profile '%s'?\n\nThis removes the selected profile from MSUF. Other profiles are not affected, but this profile cannot be restored unless you exported or copied it first."] = "'%s' 프로필을 삭제할까요?\n\n선택한 프로필을 MSUF에서 제거합니다. 다른 프로필에는 영향이 없지만, 먼저 내보내거나 복사하지 않았다면 이 프로필은 복원할 수 없습니다."
L["Discard all changes and exit?"] = "모든 변경 사항을 버리고 나가시겠습니까?"
