L["Editing %s caps. Use Caps & Icons > Max Buffs = 0 to hide buffs only for this unit; Max Debuffs = 0 hides debuffs."] = "%s 제한을 편집 중입니다. 이 유닛의 버프만 숨기려면 제한 및 아이콘 > 최대 버프 = 0을 사용하세요. 최대 디버프 = 0은 디버프를 숨깁니다."
L["Editing:"] = "편집:"
L["EM_HELP_BTN"] = "? 도움말"
L["EM_HELP_BTN_TIP"] = "전체 MSUF 설정 가이드를\n편집 모드 단계에서 엽니다."
L["EM_HELP_CDM"] = "|cff60a5ffCDM|r은 Essential Cooldown Manager 전역 앵커를 전환합니다. |cff60a5ffAnchor|r는 앵커 선택기를 엽니다. 이름 있는 프레임 위에 마우스를 올리고 Ctrl을 누른 채 왼쪽 클릭하면 전역 앵커로 사용합니다. 사용자 지정 앵커를 선택하면 CDM이 꺼집니다."
L["EM_HELP_COPYTO"] = "유닛 및 시전바 팝업에서 |cff60a5ffCopy To|r는 현재 팝업 설정을 다른 대상으로 복사합니다. 유닛프레임 복사는 대상의 위치와 앵커 설정을 유지하고, 시전바 복사는 대상 X/Y 오프셋을 유지합니다."
L["EM_HELP_DRAG"] = "이동기 오버레이에서 마우스 왼쪽 버튼을 누른 채 끌어 이동합니다. 실제 프레임은 이동기를 따라가며, 오버레이 아래 X/Y 표시가 현재 화면 오프셋을 보여줍니다. 버튼을 놓으면 위치가 저장됩니다."
L["EM_HELP_EXIT"] = "|cff60a5ffExit|r는 편집 모드를 종료하고 현재 변경 사항을 유지합니다. 전투에 들어가도 편집 모드가 종료됩니다. 팝업에서는 Escape가 닫기/취소이며, HUD의 Exit 버튼이 일반적인 종료 방법입니다."
L["EM_HELP_NUDGE"] = "화살표 키는 활성 대상을 이동합니다. 우선순위: 선택한 미리보기 핸들, 열린 시전바 팝업, 열린 오라 팝업, 현재 선택된 유닛프레임. 이동 단위: 1 px, Shift = 5 px, Ctrl = 10 px, Alt = 현재 격자 간격."
L["EM_HELP_OPACITY"] = "|cff60a5ffBG ##%|r 컨트롤을 스크롤해 편집 모드 배경 오버레이 불투명도만 변경합니다. 유닛프레임 투명도나 저장된 프레임 표시 상태는 바꾸지 않습니다."
L["EM_HELP_POPUP"] = "이동기를 끌지 않고 왼쪽 클릭하면 편집 팝업이 열립니다. 유닛 팝업은 프레임 크기, 위치, 글자 앵커, 분리된 자원 설정, 유닛으로 복사 옵션을 편집합니다. 시전바와 오라 이동기는 각각 전용 팝업을 엽니다."
L["EM_HELP_PREVIEW"] = "|cff60a5ffPreview|r는 편집 모드 중 대상, 주시, 대상의 대상, 소환수, 우두머리, 시전바 미리보기에 대한 자리표시자 데이터를 전환합니다. |cff60a5ffAuras|r는 오라 미리보기 아이콘과 오라 이동기 상자를 전환합니다."
L["EM_HELP_SNAP"] = "격자는 시각적 안내입니다. |cff60a5ffGrid ##px|r를 왼쪽 클릭하면 격자선을 켜거나 끄고, 스크롤하면 간격을 바꿉니다. |cff60a5ffSnap|r은 별도 기능입니다. 켜면 끌어 이동한 이동기가 화면 중앙 또는 다른 보이는 이동기의 가장자리/중앙에 맞춰지며 주황색 안내선이 표시됩니다."
L["EM_HELP_TITLE"] = "편집 모드 - 빠른 참고"
L["EM_HELP_UNDO"] = "|cff60a5ffUndo|r와 |cff60a5ffRedo|r는 끌기, 키 이동, 팝업 편집 전에 기록된 최근 편집 모드 변경을 복원합니다. |cff60a5ffCancel All|r는 확인 후 편집 모드 진입 전 스냅샷을 복원하고 종료합니다."
