L["Shared name shortening affects all non-player unit names and group frames unless a scope has custom font settings."] = "공유 이름 줄임은 범위가 사용자 지정 글꼴을 쓰지 않는 한 모든 비플레이어 유닛 이름과 그룹 프레임에 적용됩니다."
