L["This scope uses custom font settings. Shared name-shortening changes will not affect it until the override is reset."] = "이 범위는 사용자 지정 글꼴을 사용합니다. 재정의를 초기화하기 전까지 공유 이름 줄임 변경은 적용되지 않습니다."
