L["Blizzard mode lets WoW place the selected aura types. MSUF Custom mode lets MSUF control aura size, growth, position, filters, and styling. MSUF Dispel Highlights keep Blizzard icons while allowing MSUF's dispel border, glow, and overlay visuals."] = "Blizzard 모드는 WoW가 선택한 오라 유형을 배치하게 합니다. MSUF 사용자 지정 모드는 MSUF가 오라 크기, 성장, 위치, 필터, 스타일을 제어합니다. MSUF 해제 강조는 Blizzard 아이콘을 유지하면서 MSUF의 해제 테두리, 광채, 오버레이를 표시합니다."
L["Blizzard renderer is still active, but this group is MSUF Custom because its Use Blizzard toggle is off. Other active Blizzard aura types can still show matching spells, so duplicates can appear."] = "Blizzard 렌더러는 아직 활성 상태이지만, 이 그룹은 Blizzard 사용 스위치가 꺼져 있어 MSUF Custom입니다. 다른 활성 Blizzard 오라 유형이 일치하는 주문을 계속 표시할 수 있으므로 중복이 나타날 수 있습니다."
