L["Open Group Frames > Health & Text. It controls health colors, bars, power bar, text, dispel overlay, debuff stripe, and range fade. Heal prediction is in Global Style > Bars > Absorb Display."] = "그룹 프레임 > 생명력 및 텍스트를 여세요. 생명력 색상, 바, 자원 바, 텍스트, 해제 오버레이, 디버프 줄무늬, 거리 페이드를 제어합니다. 치유 예측은 전역 스타일 > 바 > 흡수 표시에서 설정합니다."
L["Open Unit Auras > Global Ignore List. It can hide predefined aura categories for all unit frames, or per unit after enabling Override for this unit. MSUF does not currently have an ElvUI-style freeform spell-ID blacklist for arbitrary debuffs."] = "유닛 오라 > 전역 무시 목록을 여세요. 모든 유닛 프레임의 미리 정의된 오라 범주를 숨기거나, 이 유닛에 대한 재정의를 켠 뒤 유닛별로 숨길 수 있습니다. MSUF에는 현재 임의의 약화 효과를 위한 ElvUI 방식의 자유 spell-ID 블랙리스트가 없습니다."
