L["Hover an MSUF Party, Raid, or Priority frame and press this key to pin or unpin that player."]="MSUF 파티, 공격대 또는 우선순위 프레임에 마우스를 올리고 이 키를 눌러 플레이어를 고정하거나 해제하세요."
L["No manual pins yet. While grouped, hover an MSUF Party, Raid, or Priority frame, then press your hotkey."]="수동 고정이 없습니다. 그룹에 있을 때 MSUF 파티, 공격대 또는 우선순위 프레임에 마우스를 올리고 단축키를 누르세요."
L["Use the hover hotkey above to add or remove players."]="위 마우스오버 단축키로 플레이어를 추가하거나 제거하세요."; L["Saved · not grouped"]="저장됨 · 그룹 아님"; L["Saved · not in current group"]="저장됨 · 현재 그룹에 없음"; L["Saved · Party frames disabled"]="저장됨 · 파티 프레임 꺼짐"
L["Attach the strip to the active Party, Raid, or Mythic Raid container, or choose Free position and place it with Edit Mode."]="줄을 활성 파티, 공격대 또는 신화 공격대 컨테이너에 붙이거나 자유 위치를 선택해 편집 모드에서 배치하세요."
L["Right of group frames"]="그룹 프레임 오른쪽"; L["Left of group frames"]="그룹 프레임 왼쪽"; L["Above group frames"]="그룹 프레임 위"; L["Below group frames"]="그룹 프레임 아래"; L["The strip follows the active Party, Raid, or Mythic Raid container automatically."]="줄이 활성 파티, 공격대 또는 신화 공격대 컨테이너를 자동으로 따라갑니다."; L["In party"]="파티 중"; L["In raid"]="공격대 중"; L["Not grouped"]="그룹 아님"
L["Priority Frames keep automatic tanks and manually pinned group members in a stable extra strip. In a party they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid frames. The matching base group frames must be enabled. Open Group Frames > Priority to choose who appears, set a hover hotkey, and place the strip."]="우선순위 프레임은 자동 방어 담당과 수동 고정한 파티원을 안정된 추가 줄에 표시합니다. 파티에서는 파티 프레임을, 공격대에서는 활성 공격대 또는 신화 공격대 프레임을 상속합니다. 해당 기본 그룹 프레임이 켜져 있어야 합니다. 그룹 프레임 > 우선순위에서 표시 대상, 마우스오버 단축키와 위치를 설정하세요."
L["Free position uses the dedicated Priority Frames mover."]="자유 위치는 우선순위 프레임 전용 이동기를 사용합니다."; L["How do Priority Frames work?"]="우선순위 프레임은 어떻게 작동하나요?"; L["Opens: Group Frames > Priority"]="열기: 그룹 프레임 > 우선순위"
L["Pin or unpin hovered group member"]="마우스 아래 파티원 고정 또는 해제"; L["Priority Frames hotkey"]="우선순위 프레임 단축키"; L["Left-click and press a key. Right-click, Backspace, or Delete clears it. Existing bindings are never replaced without confirmation."]="왼쪽 클릭 후 키를 누르세요. 오른쪽 클릭, Backspace 또는 Delete로 지웁니다. 기존 지정은 확인 없이 바뀌지 않습니다."
L["visible"]="표시"; L["pinned"]="고정"; L["slots"]="칸"; L["saved"]="저장"; L["Auto tanks"]="자동 방어 담당"; L["Manual only"]="수동만"; L["Attached"]="부착됨"; L["Free"]="자유"
L["Priority Frames automatic tanks"]="우선순위 프레임 자동 방어 담당"; L["Priority Frames visible slots"]="우선순위 프레임 표시 칸"; L["Priority Frames placement"]="우선순위 프레임 배치"; L["Priority Frames growth"]="우선순위 프레임 증가 방향"; L["Priority Frames spacing"]="우선순위 프레임 간격"; L["Priority Frames attachment gap"]="우선순위 프레임 부착 간격"; L["Priority Frames alignment offset"]="우선순위 프레임 정렬 오프셋"
