L["UPGRADED TO MSUF %s"] = "MSUF %s로 업그레이드됨"
L["Your MSUF 6.0 highlights"] = "MSUF 6.0 하이라이트"
L["Your current profile stays unchanged. Review %d new highlights and choose only what you want to configure."] = "현재 프로필은 변경되지 않습니다. %d의 새로운 하이라이트를 검토하고 구성하려는 항목만 선택하세요."
L["CURRENT PROFILE: %s - NO SETTINGS WILL BE CHANGED"] = "현재 프로필: %s - 설정이 변경되지 않습니다."
L["Start %d-highlight tour"] = "%d 하이라이트 투어 시작"
L["Review the release highlights without changing your current profile."] = "현재 프로필을 변경하지 않고도 릴리스 하이라이트를 검토할 수 있습니다."
L["Review exactly what you would skip before closing the tour."] = "투어를 종료하기 전에 건너뛸 내용을 정확히 검토하세요."
L["About two minutes. You can leave at any point and configure each area later."] = "약 2분 정도. 언제든지 떠날 수 있으며 나중에 각 영역을 구성할 수 있습니다."
L["Highlight %d of %d"] = "%d의 %d 강조 표시"
L["WHY IT MATTERS"] = "그것이 중요한 이유"
L["Finish tour"] = "둘러보기 종료"
L["Next highlight"] = "다음 하이라이트"
L["Mark this highlight as reviewed and continue."] = "이 하이라이트를 검토됨으로 표시하고 계속하세요."
L["Back"] = "뒤로"
L["Skip tour"] = "둘러보기 건너뛰기"
L["See the remaining highlights before deciding to skip them."] = "건너뛰기로 결정하기 전에 나머지 하이라이트를 확인하세요."
L["Skip %d remaining highlights?"] = "%d 나머지 하이라이트를 건너뛰시겠습니까?"
L["Your profile will stay safe, but you will leave these %d new configuration areas unexplored:"] = "귀하의 프로필은 안전하게 유지되지만 다음 %d 새 구성 영역은 탐색되지 않은 상태로 남겨두게 됩니다."
L["Show me the highlights"] = "하이라이트 보여줘"
L["Skip all %d and continue"] = "%d를 모두 건너뛰고 계속하세요"
L["Skipping closes this release tour only. Every setting remains available in Menu2."] = "건너뛰면 이번 출시 둘러보기만 종료됩니다. 모든 설정은 Menu2에서 계속 사용할 수 있습니다."
L["Custom Aura tracking on Unitframes"] = "유닛프레임의 맞춤형 Aura 추적"
L["Build up to three frame-specific Custom lanes on Player, Target, Focus and Boss, whitelist exact buff or debuff SpellIDs, and track your own DoTs on the Target frame with a curated per-class lane."] = "플레이어, 대상, 주시 대상, 우두머리 프레임에 최대 3개의 사용자 지정 칸을 만들고 정확한 버프·디버프 SpellID를 등록하며, 클래스별로 준비된 칸으로 대상 프레임에서 자신의 DoT를 추적하세요."
L["Your MSUF frames can act as focused WeakAura-style trackers with icons, timers, duration bars and full-frame tint, border, glow or pulse effects."] = "MSUF 프레임은 아이콘, 타이머, 지속 시간 막대 및 전체 프레임 색조, 테두리, 광선 또는 펄스 효과를 갖춘 집중된 WeakAura 스타일 추적기 역할을 할 수 있습니다."
L["three Custom Aura trackers per supported Unitframe, exact spell whitelists and full-frame effects"] = "지원되는 유닛프레임당 3개의 Custom Aura 트래커, 정확한 주문 화이트리스트 및 풀프레임 효과"
L["Build a Custom tracker"] = "사용자 정의 추적기 구축"
L["Aura settings in the right place"] = "필요한 곳에 있는 오라 설정"
L["Setup and individual styling now live in the matching Unitframe and Party/Raid menus. Appearance > Auras holds the expanded shared styles."] = "설정과 개별 스타일은 이제 해당 유닛 프레임 및 파티/공격대 메뉴에 있습니다. 외형 > 오라에는 확장된 공용 스타일이 있습니다."
L["Configure each frame in context, then use Auras for shared icon shapes, borders, shadows, colors and spacing."] = "각 프레임을 해당 메뉴에서 설정한 뒤 오라 메뉴에서 공용 아이콘 모양, 테두리, 그림자, 색상 및 간격을 조정하세요."
L["per-frame Aura controls and expanded shared styling in Appearance > Auras"] = "프레임별 오라 설정과 외형 > 오라의 확장된 공용 스타일"
L["Open shared Aura styles"] = "공용 오라 스타일 열기"
L["Adaptive Party and Raid layouts"] = "적응형 파티 및 공격대 레이아웃"
L["Party, Raid and Mythic Raid gained adaptive layouts and scaling, per-lane aura filters and blacklists, a focused Dispel Overlay page, and per-group control over whether MSUF or Blizzard draws the frames."] = "파티, 공격대, 신화 공격대에 적응형 배치와 크기 조절, 칸별 오라 필터와 차단 목록, 전용 Dispel Overlay 페이지가 추가되었고, 그룹별로 MSUF와 Blizzard 중 어느 쪽이 프레임을 그릴지 선택할 수 있습니다."
L["One group setup can follow you from a five-man into a raid, and you decide per lane which auras are allowed to show at all."] = "하나의 공격대 설정으로 5인 던전부터 공격대까지 이어서 쓸 수 있고, 어떤 효과를 표시할지 줄마다 직접 정합니다."
L["adaptive group layouts and scaling, group aura filters and blacklists, the Dispel Overlay page and the group provider controls"] = "적응형 그룹 배치와 크기 조절, 그룹 오라 필터와 차단 목록, Dispel Overlay 페이지와 그룹별 프레임 제공자 설정"
L["Open Group Layout"] = "그룹 레이아웃 열기"
L["New health values and text formats"] = "새로운 건강 값 및 텍스트 형식"
L["Health text can show abbreviated or full values with more consistent formatting, and the new Maximum Health Loss overlay can mark lost maximum health on unit and group frames."] = "생명력 텍스트는 더 일관된 형식으로 축약 값이나 전체 값을 표시할 수 있고, 새로운 최대 생명력 손실 오버레이가 유닛·그룹 프레임에서 줄어든 최대 생명력을 표시합니다."
L["You can choose compact readability or exact numbers without giving up the layout you already use."] = "이미 사용하고 있는 레이아웃을 포기하지 않고도 간결한 가독성이나 정확한 숫자를 선택할 수 있습니다."
L["the new health abbreviations, full values, text formats and the Maximum Health Loss overlay"] = "새로운 생명력 축약, 전체 값, 텍스트 형식과 최대 생명력 손실 오버레이"
L["Open HP Text Editor"] = "생명력 텍스트 편집기 열기"
L["More flexible class resources"] = "더욱 유연한 수업 리소스"
L["Class resources gained detached layouts, additional shapes and finer per-slot and full-state colors."] = "클래스 리소스는 분리된 레이아웃, 추가 모양, 더 미세한 슬롯별 및 전체 상태 색상을 얻었습니다."
L["You can move class information where your eyes already are and make important states easier to read."] = "이미 눈이 있는 곳으로 수업 정보를 이동하고 중요한 상태를 더 쉽게 읽을 수 있습니다."
L["detached class resources, new shapes and per-state colors"] = "분리된 클래스 리소스, 새로운 모양 및 상태별 색상"
L["Configure Class Resources"] = "수업 자원 구성"
L["Cast target text"] = "캐스트 대상 텍스트"
L["Target, Focus and Boss cast bars can now show who the current spell is targeting, with dedicated text styling."] = "이제 대상, 집중 및 보스 시전 바에서 전용 텍스트 스타일을 사용하여 현재 주문이 대상으로 삼고 있는 사람을 표시할 수 있습니다."
L["You can identify the destination of an important cast without shifting attention away from the cast bar."] = "캐스트 바에서 주의를 돌리지 않고도 중요한 캐스트의 목적지를 식별할 수 있습니다."
L["cast-target names and their text styling on Target, Focus and Boss frames"] = "대상, 초점 및 보스 프레임의 시전 대상 이름 및 텍스트 스타일"
L["Open Target Cast Bar"] = "타겟 캐스트 바 열기"
L["Review or skip the release highlights on the Dashboard before using first-load actions."] = "첫 번째 로드 작업을 사용하기 전에 대시보드에서 릴리스 하이라이트를 검토하거나 건너뛰세요."
L["Priority Frames for the units that matter"] = "중요한 대상을 위한 우선 순위 프레임"
L["Pin up to five group members by hand, or let MSUF pick the tanks automatically, and give them their own strip that never reshuffles mid-fight."] = "최대 다섯 명의 공대원을 직접 고정하거나 MSUF가 방어 전담을 자동으로 고르게 하고, 전투 중에도 순서가 뒤바뀌지 않는 전용 줄을 주십시오."
L["The people you have to watch keep one fixed spot on screen, with the Party or Raid look and click-casting they already had."] = "꼭 지켜봐야 하는 사람들이 화면에서 고정된 자리를 유지하며, 파티나 공격대의 외형과 클릭 시전을 그대로 사용합니다."
L["Priority Frames, manual and automatic pinning, and their own placement"] = "우선 순위 프레임, 수동 및 자동 고정, 전용 배치"
L["Set up Priority Frames"] = "우선 순위 프레임 설정"
L["One Colors page with click-to-paint"] = "클릭해서 칠하는 하나의 색상 페이지"
L["Every color moved onto one page, grouped into Player & Target, Party & Raid, Castbar, Aura, Power and Class Resource workspaces with their own live preview."] = "모든 색상이 한 페이지로 모였고, 플레이어와 대상, 파티와 공격대, 시전 막대, 효과, 기력, 직업 자원 작업 공간으로 나뉘며 각각 실시간 미리보기를 갖습니다."
L["You can click the element in the preview to paint it instead of hunting for the matching swatch, and reuse any color from a recent or saved palette."] = "맞는 색상 견본을 찾는 대신 미리보기에서 해당 요소를 클릭해 칠할 수 있고, 최근 또는 저장된 팔레트의 색을 다시 쓸 수 있습니다."
L["the rebuilt Colors page, click-to-paint previews, palettes and the new color picker"] = "새로 만든 색상 페이지, 클릭해서 칠하는 미리보기, 팔레트, 새 색상 선택기"
L["Open the Colors page"] = "색상 페이지 열기"
L["One 0-30 layer scale for everything"] = "모든 것을 위한 하나의 0-30 레이어 척도"
L["Text, status icons, auras, borders, bar outlines, group indicators and class resources all order themselves on one shared 0-30 layer scale."] = "텍스트, 상태 아이콘, 효과, 테두리, 막대 외곽선, 공격대 표시, 직업 자원이 모두 공유된 0-30 레이어 척도로 정렬됩니다."
L["You decide exactly what draws in front of what, and the Layer Overview beside any layer slider shows the whole stack at once."] = "무엇이 무엇 앞에 그려질지 정확히 정할 수 있고, 레이어 슬라이더 옆의 레이어 개요가 전체 순서를 한 번에 보여줍니다."
L["the addon-wide 0-30 layer scale and the Layer Overview"] = "애드온 전체의 0-30 레이어 척도와 레이어 개요"
L["MSUF Edit Mode, rebuilt"] = "새로 만든 MSUF 편집 모드"
L["Edit Mode gained a dockable toolbar, redesigned quick popups on every frame, and Undo and Redo that behave the same there as in the menu."] = "편집 모드에 고정 가능한 도구 모음, 모든 프레임의 새 빠른 팝업, 그리고 메뉴와 똑같이 동작하는 실행 취소와 다시 실행이 추가되었습니다."
L["You can move, size and copy frames directly on screen and step back out of any mistake without reopening the menu."] = "메뉴를 다시 열지 않고도 화면에서 바로 프레임을 옮기고 크기를 바꾸고 복사하며, 실수를 되돌릴 수 있습니다."
L["the rebuilt Edit Mode toolbar, its quick popups and shared Undo and Redo"] = "새 편집 모드 도구 모음, 빠른 팝업, 공유되는 실행 취소와 다시 실행"
L["Start Edit Mode"] = "편집 모드 시작"
L["Spell Indicators on Group Frames"] = "그룹 프레임의 Spell Indicators"
L["Track chosen buffs on Party and Raid frames as icon, square, bar or number indicators, with custom spell lists and corner indicators."] = "파티·공격대 프레임에서 선택한 버프를 아이콘, 사각형, 막대 또는 숫자로 추적하고, 사용자 지정 주문 목록과 모서리 표시기를 사용할 수 있습니다."
L["You can see missing or expiring externals and key buffs directly on the frames, with expiring icon glows, health-bar highlights and full-frame effects."] = "빠졌거나 곧 끝나는 외생기와 핵심 버프를 프레임에서 바로 확인할 수 있으며, 만료 시 아이콘 발광, 생명력 막대 강조, 프레임 전체 효과로 경고합니다."
L["Spell Indicators with custom aura lists, corner indicators and expiring-effect warnings"] = "사용자 지정 오라 목록, 모서리 표시기, 만료 경고가 있는 Spell Indicators"
L["Open Spell Indicators"] = "Spell Indicators 열기"
L["Fill Direction for Health and Power"] = "생명력·자원 채우기 방향"
L["Every Unit Frame can fill its Health and Power left to right, right to left, bottom to top or top to bottom."] = "각 유닛 프레임은 생명력과 자원을 왼쪽에서 오른쪽, 오른쪽에서 왼쪽, 아래에서 위, 위에서 아래로 채울 수 있습니다."
L["Vertical and mirrored bar layouts become a per-frame choice - something no other unit frame addon currently offers."] = "세로형·대칭형 막대 배치가 프레임별 설정이 됩니다. 현재 다른 어떤 유닛 프레임 애드온도 제공하지 않는 기능입니다."
L["the per-frame Fill Direction control for Health and Power bars"] = "생명력·자원 막대의 프레임별 채우기 방향 설정"
L["Choose a Fill Direction"] = "채우기 방향 선택"
L["Portraits: attached, detached or overlay"] = "초상화: 부착, 분리 또는 오버레이"
L["Portraits can stay attached, float freely or render as an overlay inside the health bar, with independent size, nine-point anchoring, opacity and pannable zoom."] = "초상화를 프레임에 붙이거나 자유롭게 배치하거나 생명력 막대 안에 오버레이로 그릴 수 있으며, 독립적인 크기, 9지점 고정, 투명도, 이동 가능한 확대/축소를 지원합니다."
L["Rectangular and watermark-style portraits become possible, and Relief rings plus shape-following borders frame Square, Circle, Rounded and Diamond portraits."] = "직사각형·워터마크 스타일 초상화가 가능해지고, Relief 링과 모양을 따라가는 테두리가 사각형, 원형, 둥근 모서리, 다이아몬드 초상화를 감쌉니다."
L["the new portrait placement modes, Relief rings and shape-following portrait borders"] = "새로운 초상화 배치 모드, Relief 링과 모양을 따라가는 초상화 테두리"
L["Open Portrait settings"] = "초상화 설정 열기"
L["Status icon packs"] = "상태 아이콘 팩"
L["Role, leader, raid marker, ready check and every other status icon can switch between twelve bundled styles or your own custom icons, per indicator."] = "역할, 파티장, 공격대 표식, 준비 확인 등 모든 상태 아이콘을 표시기마다 12가지 기본 스타일이나 직접 고른 아이콘으로 바꿀 수 있습니다."
L["Status icons can finally match your UI style instead of always using Blizzard art, and external packs can register through SharedMedia."] = "상태 아이콘이 Blizzard 기본 그림 대신 UI 스타일에 맞게 표시되고, 외부 팩은 SharedMedia로 등록할 수 있습니다."
L["the twelve status icon styles and per-indicator custom icons"] = "12가지 상태 아이콘 스타일과 표시기별 사용자 지정 아이콘"
L["Pick an icon style"] = "아이콘 스타일 선택"
