L["Right-click opens quick actions."] = "마우스 오른쪽 버튼을 클릭하면 빠른 작업이 열립니다."
L["double-click/settings opens options - right-click actions - arrows nudge"] = "두 번 클릭/settings 옵션 열기 - 마우스 오른쪽 버튼 클릭 동작 - 화살표 살짝 이동"
L["drag handles - double-click/settings opens options - right-click actions - Ctrl+wheel zoom"] = "핸들 끌기 - 두 번 클릭/settings 옵션 열기 - 마우스 오른쪽 버튼 클릭 작업 - Ctrl+휠 확대/축소"
L["Click a handle to select - double-click/settings opens options - right-click actions - Ctrl+wheel zoom"] = "핸들을 클릭하여 선택 - 두 번 클릭/settings 옵션 열기 - 마우스 오른쪽 버튼 클릭 작업 - Ctrl+휠 확대/축소"
L["Preview tip: drag handles to move, double-click or use settings to open options, right-click for actions."] = "미리보기 팁: 핸들을 드래그하여 이동하고, 두 번 클릭하거나 설정을 사용하여 옵션을 열고, 작업을 보려면 마우스 오른쪽 버튼을 클릭하세요."
