L["Skipping this personal step uses neutral guidance and leaves navigation, Search, autosave, Undo/Redo and page reset unexplained."] = "이 개인 단계를 건너뛰면 중립 안내가 사용되며 탐색, 검색, 자동 저장, Undo/Redo 및 페이지 재설정이 설명되지 않습니다."
L["Skipping frame placement leaves whole-frame movement, snapping, nudging and safe exit behavior unexplained."] = "프레임 배치를 건너뛰면 전체 프레임 이동, 스냅, 살짝 이동 및 안전한 종료 동작이 설명되지 않습니다."
L["Skipping the Player frame leaves its layout, text, indicators and aura options unreviewed."] = "플레이어 프레임을 건너뛰면 레이아웃, 텍스트, 표시기 및 오라 옵션이 검토되지 않은 상태로 남습니다."
L["Skipping the Target frame leaves its layout, text, indicators and aura options unreviewed."] = "대상 프레임을 건너뛰면 레이아웃, 텍스트, 표시기 및 오라 옵션이 검토되지 않은 상태로 남습니다."
L["Skipping the Focus frame leaves its layout, text, indicators and aura options unreviewed."] = "초점 프레임을 건너뛰면 레이아웃, 텍스트, 표시기 및 오라 옵션이 검토되지 않은 상태로 남습니다."
L["Skipping the Pet frame leaves its layout, text, indicators and aura options unreviewed."] = "애완 동물 프레임을 건너뛰면 레이아웃, 텍스트, 표시기 및 오라 옵션이 검토되지 않은 상태로 남습니다."
L["Skipping Target of target leaves its layout, text and visibility options unreviewed."] = "대상의 대상을 건너뛰면 해당 레이아웃, 텍스트 및 가시성 옵션이 검토되지 않은 상태로 남습니다."
L["Skipping Focus target leaves its layout, text and visibility options unreviewed."] = "포커스 대상을 건너뛰면 레이아웃, 텍스트 및 가시성 옵션이 검토되지 않은 상태로 유지됩니다."
L["Skipping Boss frames leaves their shared layout, text, indicators and aura options unreviewed."] = "보스 프레임을 건너뛰면 공유 레이아웃, 텍스트, 표시기 및 오라 옵션이 검토되지 않은 상태로 남습니다."
L["Skipping group layout leaves frame size, growth, sorting, scaling and anchoring unreviewed."] = "그룹 레이아웃을 건너뛰면 프레임 크기, 증가, 정렬, 크기 조정 및 고정이 검토되지 않은 채로 남습니다."
L["Skipping group bars leaves health, power, text, range and dispel presentation unreviewed."] = "그룹 막대를 건너뛰면 체력, 전력, 텍스트, 범위 및 해제 표시가 검토되지 않은 채로 남습니다."
L["Skipping group auras leaves group buff, debuff and spell-indicator behavior unreviewed."] = "그룹 오라를 건너뛰면 그룹 버프, 디버프 및 주문 표시 동작이 검토되지 않은 상태로 남습니다."
L["Skipping Bars leaves global textures, absorbs, outlines, highlights and power behavior unreviewed."] = "바를 건너뛰면 전역 텍스처, 흡수, 윤곽선, 하이라이트 및 전원 동작이 검토되지 않은 상태로 남습니다."
L["Skipping Cast Bars leaves cast appearance, text, empowered casts and interrupt cues unreviewed."] = "시전 바를 건너뛰면 시전 모양, 텍스트, 강화된 시전 및 인터럽트 신호가 검토되지 않은 상태로 남습니다."
L["Skipping Colors leaves frame, power, aura, class, text and castbar colors unreviewed."] = "색상을 건너뛰면 프레임, 파워, 오라, 클래스, 텍스트 및 시전바 색상이 검토되지 않은 채로 남습니다."
L["Skipping Fonts leaves the global font, text styling, colors and name shortening unreviewed."] = "글꼴을 건너뛰면 전역 글꼴, 텍스트 스타일, 색상 및 이름 단축이 검토되지 않은 상태로 유지됩니다."
L["Skipping Aura styling leaves buff/debuff size, cooldown, stacks, duration bars and ordering unreviewed."] = "Aura 스타일링을 건너뛰면 buff/debuff 크기, 재사용 대기시간, 스택, 지속 시간 표시줄 및 주문이 검토되지 않은 채로 남습니다."
L["Skipping Miscellaneous leaves language, menu behavior, startup, tooltips and Blizzard-frame integration unreviewed."] = "기타를 건너뛰면 언어, 메뉴 동작, 시작, 툴팁 및 블리자드 프레임 통합이 검토되지 않은 채로 남습니다."
L["Skipping Class Resources leaves class layout, behavior, style, visibility and alternative power displays unreviewed."] = "클래스 리소스를 건너뛰면 클래스 레이아웃, 동작, 스타일, 가시성 및 대체 전원 표시가 검토되지 않은 채로 남습니다."
L["Skipping Gameplay leaves combat timers, state behavior, class toggles and the combat crosshair unreviewed."] = "게임플레이를 건너뛰면 전투 타이머, 상태 동작, 클래스 토글 및 전투 십자선이 검토되지 않은 상태로 남습니다."
L["Skipping Profiles leaves profile management, specialization assignment and export/import backup unreviewed."] = "프로필을 건너뛰면 프로필 관리, 전문화 할당 및 내보내기/import 백업이 검토되지 않은 상태로 남습니다."
L["Skipping the final review hides the summary, but does not change any setting."] = "최종 검토를 건너뛰면 요약이 숨겨지지만 설정은 변경되지 않습니다."
