L["Choose one answer in each row. You can skip this personal step at any time."] = "각 행에서 하나의 답변을 선택하세요. 언제든지 이 개인 단계를 건너뛸 수 있습니다."
L["Drag whole frames, use arrows for precision, and Exit to keep your placement."] = "전체 프레임을 드래그하고 화살표를 사용하여 정밀도를 높인 다음 종료하여 배치를 유지하세요."
L["Start with Preview, then follow each highlighted frame section."] = "미리보기로 시작한 다음 강조 표시된 각 프레임 섹션을 따라가세요."
L["Raid focus: compare Raid and Mythic scopes before reviewing each highlighted section."] = "Raid 초점: 강조 표시된 각 섹션을 검토하기 전에 Raid 및 Mythic 범위를 비교하십시오."
L["Solo focus: keep group defaults or prepare the Party scope for occasional groups."] = "솔로 포커스: 그룹 기본값을 유지하거나 가끔 그룹을 위한 파티 범위를 준비합니다."
L["Dungeon focus: begin with Party or Mythic scope, then review each highlighted section."] = "던전 초점: 파티 또는 신화 범위로 시작한 다음 강조 표시된 각 섹션을 검토하세요."
L["Compare the Party, Raid or Mythic scope that matters to you, then follow the highlights."] = "귀하에게 중요한 파티, 레이드 또는 신화 범위를 비교한 다음 주요 내용을 따르십시오."
L["Sample = visual only · tests = temporary · scope = shared/unit/group"] = "샘플 = 시각적 전용 · 테스트 = 임시 · 범위 = 공유/unit/group"
L["Simulate casts here; position castbar handles in Preview or MSUF Edit Mode."] = "여기에서 캐스트를 시뮬레이션하세요. 미리보기 또는 MSUF 편집 모드에서 Castbar 핸들을 배치합니다."
L["Use the scope selector for shared, unit and group text; compare readability in Preview."] = "공유, 단위 및 그룹 텍스트에 범위 선택기를 사용하십시오. 미리보기에서 가독성을 비교해보세요."
L["Live/Dummy = display only · colored handles = saved positions · scope = shared/unit/group/custom"] = "Live/Dummy = 표시 전용 · 색상 핸들 = 저장된 위치 · 범위 = 공유/unit/group/custom"
L["Use the interactive preview for layouts and states; use Edit Mode for whole-frame placement."] = "레이아웃과 상태에 대한 대화형 미리보기를 사용하세요. 전체 프레임 배치에는 편집 모드를 사용하십시오."
L["Finish with a profile check and export a backup of your setup."] = "프로필 확인을 마치고 설정 백업을 내보냅니다."
L["Review your choices and skipped areas. Finish adds no extra setting changes."] = "선택 사항과 건너뛴 영역을 검토하세요. 마침은 추가 설정 변경을 추가하지 않습니다."
L["Clarity focus: prefer the simplest readable option in each highlighted section."] = "명확성에 초점: 강조 표시된 각 섹션에서 가장 간단하게 읽을 수 있는 옵션을 선호합니다."
L["Combat-detail focus: inspect indicators, timers and visibility in each highlighted section."] = "전투 세부 사항 초점: 강조 표시된 각 섹션의 표시기, 타이머 및 가시성을 검사합니다."
L["Review the highlighted sections; previews update while your changes autosave."] = "강조 표시된 섹션을 검토하세요. 변경 사항이 자동 저장되는 동안 미리보기가 업데이트됩니다."
L[" and %d more"] = "그리고 %d 더보기"
