L["Personalizes guided setup hints without changing MSUF settings."] = "MSUF 설정을 변경하지 않고도 안내식 설정 힌트를 개인화합니다."
L["Two quick choices make the guide fit how you play."] = "두 가지 빠른 선택을 통해 가이드가 귀하의 플레이 방식에 적합하게 됩니다."
L["Where do you spend most of your time?"] = "대부분의 시간을 어디에서 보내시나요?"
L["How much combat information should stand out?"] = "얼마나 많은 전투 정보가 눈에 띄어야 합니까?"
L["Navigate and find"] = "탐색 및 찾기"
L["Use the left rail for pages and Search for an exact native control."] = "페이지의 왼쪽 레일을 사용하고 정확한 기본 컨트롤을 검색하세요."
L["Autosave and history"] = "자동 저장 및 기록"
L["Changes autosave. Undo and Redo restore recent edits; Pause saves this exact tour position."] = "자동 저장을 변경합니다. 실행 취소 및 다시 실행은 최근 편집 내용을 복원합니다. 일시 정지는 정확한 둘러보기 위치를 저장합니다."
L["Reset with intent"] = "의도적으로 재설정"
L["Reset All affects only the current supported page and asks first."] = "모두 재설정은 현재 지원되는 페이지에만 영향을 미치며 먼저 묻습니다."
L["Move whole frames safely"] = "전체 프레임을 안전하게 이동"
L["Preview moves inner elements; MSUF Edit Mode places complete frames."] = "미리보기는 내부 요소를 이동합니다. MSUF 편집 모드에서는 전체 프레임을 배치합니다."
L["What you can move"] = "이동할 수 있는 것"
L["Unitframes, supported castbars, group containers, aura groups and the tooltip preview. Boss 1 moves the shared Boss layout."] = "유닛프레임, 지원되는 시전바, 그룹 컨테이너, 오라 그룹 및 툴팁 미리보기. Boss 1은 공유 Boss 레이아웃을 이동합니다."
L["Drag, select and align"] = "드래그, 선택 및 정렬"
L["Drag to place; click for quick controls. Arrow keys nudge, while Grid and Snap align."] = "드래그하여 배치하세요. 빠른 제어를 위해 클릭하세요. 화살표 키는 그리드와 스냅이 정렬되는 동안 조금씩 움직입니다."
L["Undo, Cancel All, Exit"] = "실행 취소, 모두 취소, 종료"
L["Undo and Redo affect individual moves. Cancel All restores the entry snapshot; Exit keeps your work."] = "실행 취소 및 다시 실행은 개별 이동에 영향을 미칩니다. 모두 취소는 항목 스냅샷을 복원합니다. 종료하면 작업이 유지됩니다."
L["Combat pauses safely"] = "전투가 안전하게 일시 중지됩니다."
L["Combat closes the menu and Edit Mode but keeps changes made so far. Reopen MSUF afterward to resume here."] = "전투에서는 메뉴와 편집 모드가 닫히지만 지금까지의 변경 사항은 유지됩니다. 여기에서 재개하려면 나중에 MSUF를 다시 여세요."
L["Open MSUF Edit Mode"] = "MSUF 편집 모드 열기"
L["MSUF Edit Mode is active"] = "MSUF 편집 모드가 활성화되었습니다."
L["Ready to place frames"] = "프레임 배치 준비 완료"
L["Use the Edit Mode HUD; Exit keeps the result."] = "편집 모드 HUD를 사용하세요. Exit는 결과를 유지합니다."
L["This opens the in-game placement HUD."] = "그러면 게임 내 배치 HUD가 열립니다."
L["Exit and keep changes"] = "종료하고 변경사항 유지"
L["Open or exit MSUF Edit Mode"] = "MSUF 편집 모드 열기 또는 종료"
L["Moves whole MSUF frames and group containers; exiting keeps changes."] = "전체 MSUF 프레임과 그룹 컨테이너를 이동합니다. 종료하면 변경 사항이 유지됩니다."
L["Finishing records the tour as complete and changes nothing else."] = "마무리는 투어를 완료된 것으로 기록하고 다른 것은 변경하지 않습니다."
