L["Guided Setup"] = "안내 설정"
L["Your current frames stay active. Follow the complete guided setup, import a profile safely, or keep playing with your existing setup."] = "현재 프레임은 활성 상태로 유지됩니다. 전체 안내 설정을 따르거나, 안전하게 프로필을 가져오거나, 기존 설정을 계속 사용해 보세요."
L["Your frames are ready now. Follow the complete guided setup, import a profile, or start playing with the defaults."] = "이제 프레임이 준비되었습니다. 전체 안내 설정을 따르거나, 프로필을 가져오거나, 기본값으로 플레이를 시작하세요."
L["FULL GUIDED SETUP"] = "전체 안내 설정"
