L["Browse releases from 6.02 onward. Highlight links open the matching feature directly in the MSUF menu."] = "6.02 이후 릴리스를 살펴보세요. 하이라이트 링크는 MSUF 메뉴에서 해당 기능을 바로 엽니다."
