L["No"] = "아니요"
L["No blacklisted spells. Add one above or use a preset."] = "블랙리스트에 등록된 주문이 없습니다. 위에 하나를 추가하거나 사전 설정을 사용하세요."
L["No blacklisted spells. Add one from the presets above."] = "블랙리스트에 등록된 주문이 없습니다. 위의 사전 설정에서 하나를 추가하세요."
L["No blocked spells. Add one above or use a preset."] = "차단된 주문이 없습니다. 위에 하나를 추가하거나 사전 설정을 사용하세요."
L["No blocked spells. Add one from the presets above."] = "차단된 주문이 없습니다. 위의 사전 설정에서 하나를 추가하세요."
L["No layers match this search."] = "이 검색과 일치하는 레이어가 없습니다."
L["No nameplate cast events are registered while disabled."] = "비활성화된 동안에는 네임플레이트 캐스트 이벤트가 등록되지 않습니다."
L["No public aura category data is loaded."] = "공개 Aura 카테고리 데이터가 로드되지 않습니다."
L["No spells tracked. Add up to 40 exact SpellIDs."] = "추적된 주문이 없습니다. 정확한 SpellID를 최대 40개까지 추가하세요."
L["Normal"] = "보통"
L["On previews every enabled spell of every tracked spec, including spells that only draw a frame effect. Off previews only the selected spell."] = "켜면 추적 중인 모든 전문화의 활성화된 주문을 모두 미리 보며, 테두리 효과만 그리는 주문도 포함됩니다. 끄면 선택한 주문만 미리 봅니다."
L["Opacity remains beside the setting when that element supports it."] = "해당 요소가 지원하는 경우 불투명도는 설정 옆에 유지됩니다."
L["Open Aura Style"] = "오픈 오라 스타일"
L["Open Bars"] = "오픈 바"
L["Open Colors > Bar Gradient Colors for separate Health and Power gradient colors in the selected Bars scope."] = "선택한 막대 범위에서 별도의 상태 및 전력 그라데이션 색상을 보려면 색상 > 막대 그라데이션 색상을 엽니다."
L["Open Colors > Group Frame Colors for shared Party, Raid and Mythic Raid colors."] = "공유된 파티, Raid 및 Mythic Raid 색상을 보려면 색상 > 그룹 프레임 색상을 엽니다."
L["Open Edit Mode and move Party Frames"] = "편집 모드 열기 및 파티 프레임 이동"
L["Open Group Frames > Auras for Buff/Debuff filters, lists, visibility, and layout. For text, cooldowns, stacks, and duration bars use Appearance > Auras and select Party or Raid scope."] = "버프/디버프 필터, 목록, 가시성 및 레이아웃을 보려면 그룹 프레임 > 오라를 엽니다. 텍스트, 재사용 대기시간, 스택 및 지속 시간 표시줄의 경우 모양 > 오라를 사용하고 파티 또는 레이드 범위를 선택하세요."
L["Open Group Frames > Layout. Text, Resource Bar, and Range Fade are arranged beside Frame Basics and Transparency. Dispel Overlay and Debuff Stripe are on the Dispel Overlay page. Heal prediction is in Global Style > Bars > Absorb Display."] = "그룹 프레임 > 레이아웃을 엽니다. 텍스트, 리소스 표시줄 및 범위 페이드는 프레임 기본 및 투명도 옆에 정렬됩니다. Dispel Overlay 및 Debuff Stripe은 Dispel Overlay 페이지에 있습니다. 치유 예측은 전역 스타일 > 바 > 흡수 표시에 있습니다."
L["Open it and choose a different value."] = "그것을 열고 다른 값을 선택하십시오."
L["Open the affected UnitFrame > Auras > Debuffs and enable the native Dispellable rule. For Party/Raid use Group Frames > Auras > Debuffs."] = "영향을 받은 UnitFrame > Auras > Debuffs를 열고 기본 Dispellable 규칙을 활성화하세요. 파티/레이드의 경우 그룹 프레임 > 오라 > 디버프를 사용하세요."
L["Open the affected UnitFrame > Auras > Debuffs and use its frame-specific SpellID blacklist. Group exclusions live directly in Group Frames > Auras > Debuffs."] = "영향을 받은 UnitFrame > Auras > Debuffs를 열고 해당 프레임별 SpellID 블랙리스트를 사용하세요. 그룹 제외는 그룹 프레임 > 오라 > 디버프에 직접 적용됩니다."
L["Open the affected UnitFrame > Auras and choose Buffs or Debuffs. Check its frame-specific Blizzard filters, blacklist, enabled state, and icon cap. For Party/Raid use Group Frames > Auras."] = "영향을 받은 UnitFrame > Auras를 열고 버프 또는 디버프를 선택하세요. 프레임별 블리자드 필터, 블랙리스트, 활성화 상태 및 아이콘 캡을 확인하세요. 파티/레이드의 경우 그룹 프레임 > 오라를 사용하세요."
L["Open the affected UnitFrame > Auras for visibility, layout, filters, and blacklists. Use Appearance > Auras for scope-aware cooldown, stack, duration-bar, and icon styling."] = "가시성, 레이아웃, 필터 및 블랙리스트를 보려면 영향을 받은 UnitFrame > Auras를 엽니다. 범위 인식 쿨다운, 스택, 지속 시간 표시줄 및 아이콘 스타일을 지정하려면 모양 > 오라를 사용하세요."
L["Open the frame and expand Auras. Buffs and Debuffs contain their own Blizzard filters and blacklists; Custom 1-3 contains its own whitelist. There is no separate Filter tab."] = "프레임을 열고 Auras를 확장하세요. 버프와 디버프에는 자체 블리자드 필터와 블랙리스트가 포함되어 있습니다. 사용자 정의 1-3에는 자체 화이트리스트가 포함되어 있습니다. 별도의 필터 탭이 없습니다."
L["Open the matching color section below."] = "아래에서 일치하는 색상 섹션을 엽니다."
L["Opens Buff styling for this frame. Spell choice, placement, size, layer, and frame highlight stay unique to this indicator."] = "이 프레임에 대한 버프 스타일을 엽니다. 주문 선택, 배치, 크기, 레이어 및 프레임 강조 표시는 이 표시기에 고유하게 유지됩니다."
L["Opens: Group Frames > Auras"] = "열림: 그룹 프레임 > 오라"
L["Opens: Group Frames > Status & Indicators"] = "열림: 그룹 프레임 > 상태 및 표시기"
L["Opens: Target > Auras"] = "열림: 대상 > 오라"
L["Original"] = "원본"
L["Out of range"] = "범위를 벗어남"
L["Outline color"] = "외곽선 색상"
L["Over-absorb overlay"] = "과잉 흡수 오버레이"
L["PART 1 - Build Player once, then copy the finished setup to the other Unitframes."] = "1부 - 플레이어를 한 번 빌드한 다음 완성된 설정을 다른 유닛프레임에 복사합니다."
L["PART 2 - Build Party once, then copy it to Raid or Mythic Raid."] = "2부 - 파티를 한 번 만든 다음 Raid 또는 Mythic Raid에 복사하세요."
L["PART 3 - Shape Class Resources with its interactive preview and cooldown-aware anchoring."] = "3부 - 대화형 미리보기 및 쿨다운 인식 앵커링을 통해 클래스 리소스를 형성합니다."
L["PARTY CORE - Change the new green setting and watch the Party Preview update."] = "PARTY CORE - 새로운 녹색 설정을 변경하고 파티 미리보기 업데이트를 시청하세요."
L["PARTY IS THE MASTER - Adjust its frame basics, then copy the finished result to Raid or Mythic Raid."] = "파티가 주인입니다 - 프레임 기본을 조정한 다음 완성된 결과를 Raid 또는 Mythic Raid에 복사하세요."
L["PLAYER CORE - Change the new green setting and watch the same Player Preview update."] = "플레이어 코어 - 새로운 녹색 설정을 변경하고 동일한 플레이어 미리보기 업데이트를 시청하세요."
L["PLAYER IS THE MASTER - Change the highlighted frame basics; the Live Preview updates immediately."] = "플레이어가 마스터입니다 - 강조 표시된 프레임 기본 사항을 변경하세요. 실시간 미리보기가 즉시 업데이트됩니다."
