L["Two arrows point to a movable frame. Drag it once; Next unlocks after a real position change."] = "두 개의 화살표는 이동식 프레임을 가리킵니다. 한 번 드래그하세요. 실제 위치 변경 후 다음이 잠금 해제됩니다."
L["Type a new value, then press Enter."] = "새 값을 입력한 다음 Enter 키를 누릅니다."
L["UNLOCK, THEN CHANGE IT - Enable Corner Indicators, choose a slot, then select Custom Spell when requested."] = "잠금 해제 후 변경 - 코너 표시기를 활성화하고 슬롯을 선택한 다음 요청 시 맞춤 주문을 선택하세요."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spec, then press a tracked spell tile."] = "잠금 해제 후 변경 - 주문 표시기를 활성화하고 사양을 선택한 다음 추적된 주문 타일을 누르세요."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spell, then select a Frame Effect."] = "잠금 해제 후 변경 - 주문 표시기를 활성화하고 주문을 선택한 다음 프레임 효과를 선택하세요."
L["UNLOCK, THEN CHANGE IT - Enable Spell Indicators, choose a spell, then set Indicator Type."] = "잠금 해제 후 변경 - 철자 표시를 활성화하고 철자를 선택한 다음 표시 유형을 설정하세요."
L["UNLOCK, THEN CHANGE IT - Enable the parent feature in this section first."] = "잠금 해제 후 변경 - 먼저 이 섹션에서 상위 기능을 활성화하세요."
L["UNLOCK, THEN CHANGE IT - Turn on Spell Indicators in the earlier checkpoint; use Back if you skipped it."] = "잠금을 해제한 후 변경하세요. - 이전 체크포인트에서 철자 표시기를 켭니다. 건너뛴 경우 뒤로를 사용하세요."
L["Unit frame status icons are on each unit page. Group Spell Indicators are in Group Frames > Auras; group status and corner indicators are in Group Frames > Status & Indicators."] = "유닛 프레임 상태 아이콘은 각 유닛 페이지에 있습니다. 그룹 주문 표시기는 그룹 프레임 > 오라에 있습니다. 그룹 상태 및 모서리 표시기는 그룹 프레임 > 상태 및 표시기에 있습니다."
