L["+"] = "+"
L["Can Priority Frames automatically select healers, DPS, classes, or specs?"] = "우선 순위 프레임이 힐러, DPS, 클래스 또는 전문화를 자동으로 선택할 수 있습니까?"
L["Can Priority Frames automatically show Augmentation Evokers?"] = "우선 순위 프레임에 증강 유발자가 자동으로 표시될 수 있나요?"
L["Can Priority Frames show my co-tank?"] = "우선 순위 프레임에 내 공동 탱크가 표시될 수 있나요?"
L["Can Priority Frames update during combat?"] = "전투 중에 우선순위 프레임을 업데이트할 수 있나요?"
L["Check that Priority Frames are enabled, you are grouped, and the matching base Party or Raid frames are enabled. Confirm that an assigned tank or manually pinned player is currently in the group and Visible slots is not full. Saved absent players create no empty placeholders, and protected roster changes made in combat finish after combat ends."] = "우선 순위 프레임이 활성화되어 있는지, 그룹화되어 있는지, 일치하는 기본 파티 또는 공격대 프레임이 활성화되어 있는지 확인하세요. 할당된 탱크 또는 수동으로 고정된 플레이어가 현재 그룹에 있고 표시 슬롯이 가득 차지 않았는지 확인하세요. 저장된 결석 플레이어는 빈 자리 표시자를 생성하지 않으며, 전투가 끝난 후 전투 종료 시 명단 변경 사항이 보호됩니다."
L["Class Color and Health Gradient are runtime colors, not a single editable swatch."] = "클래스 색상 및 상태 그라데이션은 편집 가능한 단일 견본이 아닌 런타임 색상입니다."
L["Cleave Training Dummy"] = "클리브 트레이닝 더미"
L["Custom 1-3 are always stored per frame. Icon styling and Full-Frame effects here only change "] = "사용자 정의 1-3은 항상 프레임별로 저장됩니다. 여기에서는 아이콘 스타일과 전체 프레임 효과만 변경됩니다."
L["Disabled or whitelist empty"] = "비활성화되었거나 허용 목록이 비어 있습니다."
L["Do Priority Frame pins persist, and what order do they use?"] = "우선순위 프레임 핀은 지속되며 어떤 순서로 사용됩니까?"
L["Do Priority Frames inherit click casting and appearance?"] = "우선순위 프레임은 클릭 캐스팅 및 모양을 상속합니까?"
L["Do Priority Frames use polling?"] = "우선순위 프레임은 폴링을 사용합니까?"
L["Do Priority Frames work in parties and dungeons?"] = "우선 순위 프레임은 파티와 던전에서 작동합니까?"
L["Enter text"] = "텍스트를 입력하세요"
L["Existing Priority frames remain usable in combat, but WoW protects secure group-frame membership and layout changes. Any pin, roster, slot, or placement change that needs a secure refresh is applied after combat ends. Change the Priority Frames keybinding out of combat."] = "기존 우선 순위 프레임은 전투 중에 계속 사용할 수 있지만 WoW는 안전한 그룹 프레임 멤버십 및 레이아웃 변경을 보호합니다. 안전한 새로 고침이 필요한 핀, 명단, 슬롯 또는 배치 변경 사항은 전투가 끝난 후 적용됩니다. 전투 중 우선 순위 프레임 키 바인딩을 변경합니다."
L["Follows Unitframe Global Coloring. The swatch previews the current global bar color."] = "유닛프레임 글로벌 컬러링을 따릅니다. 견본은 현재 전역 막대 색상을 미리 봅니다."
L["For Priority Frames, layout is profile-wide, while pins are character-specific. Visible slots can be set from one to five. Automatic tanks fill first, followed by manual pins in saved order; duplicate selections appear once. A saved player who is absent waits until that player rejoins the current group."] = "우선 순위 프레임의 경우 레이아웃은 프로필 전체에 적용되는 반면 핀은 문자별로 적용됩니다. 표시되는 슬롯은 1~5개까지 설정할 수 있습니다. 자동 탱크가 먼저 채워지고 저장된 순서대로 수동 핀이 채워집니다. 중복 선택 항목이 한 번 나타납니다. 결석한 저장된 플레이어는 해당 플레이어가 현재 그룹에 다시 합류할 때까지 기다립니다."
L["Frames"] = "프레임"
L["How do I pin or unpin a player in Priority Frames?"] = "우선 순위 프레임에서 플레이어를 고정하거나 고정 해제하려면 어떻게 해야 하나요?"
L["How do I position Priority Frames?"] = "우선순위 프레임을 어떻게 배치합니까?"
L["How should an Augmentation Evoker use Priority Frames?"] = "Augmentation Evoker는 우선순위 프레임을 어떻게 사용해야 합니까?"
L["Inherited: this scope follows Shared aura style. Enable custom aura style only when this scope needs different text, swipe, border, or timer settings."] = "상속됨: 이 범위는 공유 오라 스타일을 따릅니다. 이 범위에 다른 텍스트, 스와이프, 테두리 또는 타이머 설정이 필요한 경우에만 사용자 정의 오라 스타일을 활성화하세요."
L["Leave text"] = "텍스트 남기기"
L["Live "] = "라이브"
L["Live preview is unavailable for this container. Sample mode remains available."] = "이 컨테이너에서는 실시간 미리보기를 사용할 수 없습니다. 샘플 모드는 계속 사용할 수 있습니다."
L["Live preview updates after combat. Sample mode remains available."] = "전투 후 실시간 미리보기 업데이트. 샘플 모드는 계속 사용할 수 있습니다."
L["Manually pin the teammates you want to keep visible for monitoring or click-casting. Priority Frames does not decide who should receive Prescience or Ebon Might. Configure Group Frames > Auras > Spell Indicators if you want inherited Priority frames to show Prescience, Ebon Might, Shifting Sands, Blistering Scales, or other configured effects."] = "모니터링 또는 클릭 캐스팅을 위해 계속 표시하려는 팀원을 수동으로 고정하세요. Priority Frames는 누가 Prescience나 Ebon Might를 받아야 하는지 결정하지 않습니다. 상속된 우선 순위 프레임에 Prescience, Ebon Might, Shifting Sands, Blistering Scales 또는 기타 구성된 효과를 표시하려면 그룹 프레임 > 오라 > 주문 표시기를 구성하세요."
L["Native · "] = "네이티브 ·"
L["No continuous polling ticker or OnUpdate loop is used for Priority selection. It resolves the roster when configuration, pins, group state, or relevant unit identity changes require a refresh. Automatic selection reads WoW's assigned TANK role and does not inspect every group member's specialization in the background."] = "우선순위 선택에는 연속 폴링 티커나 OnUpdate 루프가 사용되지 않습니다. 구성, 핀, 그룹 상태 또는 관련 장치 ID 변경으로 인해 새로 고침이 필요한 경우 명단을 확인합니다. 자동 선택은 WoW에 할당된 TANK 역할을 읽고 백그라운드에서 모든 그룹 구성원의 전문화를 검사하지 않습니다."
L["No live "] = "라이브 없음"
L["No live member"] = "실시간 회원 없음"
L["No matching aura active"] = "일치하는 오라가 활성화되지 않음"
L["No. Automatic selection currently uses only WoW's assigned TANK role. Healers, DPS, classes, specializations, and support targets must be pinned manually with the hover hotkey. This avoids background inspection or polling and keeps the selection deterministic."] = "아니요. 자동 선택은 현재 WoW에 할당된 TANK 역할만 사용합니다. 힐러, DPS, 클래스, 전문화 및 지원 대상은 호버 단축키를 사용하여 수동으로 고정해야 합니다. 이렇게 하면 배경 조사나 폴링이 방지되고 선택이 결정적으로 유지됩니다."
L["Open Group Frames > Priority > Placement. Attach the strip to the right, left, top, or bottom of the active Party/Raid container, or choose Free position and use the dedicated Priority Frames mover in Edit Mode. The same page controls growth, spacing, attachment gap, and alignment offset."] = "그룹 프레임 > 우선 순위 > 배치를 엽니다. 활성 파티/레이드 컨테이너의 오른쪽, 왼쪽, 상단 또는 하단에 스트립을 부착하거나 자유 위치를 선택하고 편집 모드에서 전용 우선순위 프레임 이동기를 사용하십시오. 동일한 페이지에서 성장, 간격, 부착 간격 및 정렬 오프셋을 제어합니다."
L["Override active: this scope keeps its own aura style. Shared style changes will not replace it until the override is reset."] = "재정의 활성: 이 범위는 고유한 오라 스타일을 유지합니다. 공유 스타일 변경 사항은 재정의가 재설정될 때까지 이를 대체하지 않습니다."
L["Priority Frames does not automatically detect other players' specializations. Automatic selection currently supports WoW-assigned tanks only. Pin an Augmentation Evoker manually with the hover hotkey; Priority Frames does not choose ideal Prescience or Ebon Might targets."] = "우선 순위 프레임은 다른 플레이어의 전문화를 자동으로 감지하지 않습니다. 자동 선택은 현재 WoW에 할당된 탱크만 지원합니다. 호버 단축키를 사용하여 증강 소환사를 수동으로 고정하세요. 우선순위 프레임은 이상적인 Prescience 또는 Ebon Might 대상을 선택하지 않습니다."
L["Priority Frames duplicate automatic tanks and manually pinned current group members into a stable extra strip without removing them from the normal Party or Raid frames. In a party they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid frames. They work in parties, raids, and Mythic raids, inherit the active group-frame click-cast behavior, and require the matching base group frames to be enabled."] = "우선 순위 프레임은 자동 탱크를 복제하고 현재 그룹 구성원을 수동으로 고정하여 일반 파티 또는 공격대 프레임에서 제거하지 않고 안정적인 추가 스트립에 추가합니다. 파티에서는 파티 프레임을 상속받습니다. 공격대에서는 활성 공격대 또는 신화 공격대 프레임을 상속합니다. 파티, 공격대, 신화 공격대에서 작동하며 활성 그룹 프레임 클릭 시전 동작을 상속하며 일치하는 기본 그룹 프레임을 활성화해야 합니다."
L["Shared aura style is the baseline for unit-frame aura text, swipe, border, and timer settings. Party and Raid are group-frame style scopes with their own settings."] = "공유 오라 스타일은 단위 프레임 오라 텍스트, 스와이프, 테두리, 타이머 설정의 기준이 됩니다. Party와 Raid는 자체 설정이 있는 그룹 프레임 스타일 범위입니다."
L["Textures are shared except Party/Raid group-frame overrides. Gradients can be customized per unit or group scope."] = "파티/레이드 그룹 프레임 재정의를 제외하고 텍스처는 공유됩니다. 그라데이션은 단위 또는 그룹 범위별로 사용자 정의할 수 있습니다."
L["This group scope can use custom textures and gradients. Raid also applies to Mythic Raid."] = "이 그룹 범위는 사용자 정의 텍스처와 그라데이션을 사용할 수 있습니다. Raid는 Mythic Raid에도 적용됩니다."
L["This scope can use custom gradients and bar settings. Textures still follow Shared."] = "이 범위는 사용자 정의 그라데이션 및 막대 설정을 사용할 수 있습니다. 텍스처는 여전히 공유를 따릅니다."
L["This scope follows Shared bar settings. Turn on custom settings here when this scope needs different gradients or bar settings."] = "이 범위는 공유 표시줄 설정을 따릅니다. 이 범위에 다른 그라데이션이나 막대 설정이 필요한 경우 여기에서 사용자 정의 설정을 켜십시오."
L["Updates after combat"] = "전투 후 업데이트"
L["Where can I request a Priority Frames feature?"] = "우선순위 프레임 기능은 어디에서 요청할 수 있나요?"
L["While grouped, set the hover hotkey on Group Frames > Priority. Hover an MSUF Party, Raid, or Priority frame and press the Priority Frames hotkey to pin or unpin that player. Players cannot be added by typing a name or while outside the current group; a saved absent pin waits and reappears when that player rejoins."] = "그룹화되어 있는 동안 그룹 프레임 > 우선순위에 호버 단축키를 설정하세요. MSUF 파티, Raid 또는 우선 순위 프레임에 마우스를 놓고 우선 순위 프레임 단축키를 눌러 해당 플레이어를 고정하거나 고정 해제합니다. 이름을 입력하거나 현재 그룹 외부에서는 플레이어를 추가할 수 없습니다. 저장된 부재중 핀은 기다렸다가 해당 플레이어가 다시 합류하면 다시 나타납니다."
L["Why are my Priority Frames empty or missing?"] = "내 우선순위 프레임이 비어 있거나 누락된 이유는 무엇입니까?"
L["Yes. Include tanks automatically selects current group members whose WoW-assigned role is TANK, normally including both you and your co-tank. To show only your co-tank, disable automatic tanks and manually pin the other tank. If WoW has not assigned that player the TANK role, manual pinning is the fallback."] = "그렇습니다. 탱크 포함은 WoW에서 할당한 역할이 TANK인 현재 그룹 구성원을 자동으로 선택하며, 일반적으로 귀하와 공동 탱크를 모두 포함합니다. 공동 탱크만 표시하려면 자동 탱크를 비활성화하고 다른 탱크를 수동으로 고정하세요. WoW가 해당 플레이어에게 TANK 역할을 할당하지 않은 경우 수동 고정이 대체됩니다."
L["Yes. Priority Frames inherit the active Party, Raid, or Mythic Raid frame appearance, including configured bars, text, auras, status indicators, and spell indicators. They use the same MSUF click-casting registration and unit behavior, so existing click-cast bindings also work on the duplicated frames."] = "그렇습니다. 우선 순위 프레임은 구성된 막대, 텍스트, 오라, 상태 표시 및 주문 표시를 포함하여 활성 파티, Raid 또는 Mythic Raid 프레임 모양을 상속합니다. 동일한 MSUF 클릭 캐스팅 등록 및 단위 동작을 사용하므로 기존 클릭 캐스팅 바인딩도 중복된 프레임에서 작동합니다."
L["Yes. Priority Frames work in parties, raids, and Mythic raids. In a party or dungeon they inherit Party Frames; in a raid they inherit the active Raid or Mythic Raid setup. They do not create a solo strip, and the matching base Party or Raid frames must be enabled."] = "그렇습니다. 우선 순위 프레임은 파티, 공격대, 신화 공격대에서 작동합니다. 파티나 던전에서는 파티 프레임을 상속받습니다. 공격대에서는 활성 공격대 또는 신화 공격대 설정을 상속합니다. 솔로 스트립을 생성하지 않으며 일치하는 기본 파티 또는 Raid 프레임을 활성화해야 합니다."
