L["Solid draws a crisp pixel ring around the icon. Soft Glow adds a halo, and Shadow shades the icon's own edges. The Blizzard entries and any LibSharedMedia border are drawn as edge art. Thickness scales the edge."] = "단색은 아이콘 주위에 선명한 픽셀 테두리를 그립니다. 부드러운 광채는 후광을 더하고, 그림자는 아이콘 자체의 가장자리를 어둡게 합니다. Blizzard 항목과 모든 LibSharedMedia 테두리는 가장자리 이미지로 그려집니다. 두께가 가장자리 크기를 조절합니다."
--- Slash command registry (6.0 Beta 29)
L["Frames and Edit Mode"] = "프레임 및 편집 모드"
L["Profiles and resets"] = "프로필 및 초기화"
L["Other commands"] = "기타 명령어"
L["Type /msuf help all to also list the diagnostic commands."] = "진단 명령어까지 보려면 /msuf help all 을 입력하세요."
L["List every MSUF command that is currently loaded."] = "현재 불러온 모든 MSUF 명령어를 표시합니다."
L["Print the addon version, the active profile and the Edit Mode state."] = "애드온 버전, 활성 프로필, 편집 모드 상태를 출력합니다."
L["Reload the interface, same as /rl."] = "인터페이스를 다시 불러옵니다. /rl 과 동일합니다."
L["Reload the interface."] = "인터페이스를 다시 불러옵니다."
L["Toggle the absorb bars on and off."] = "흡수량 바를 켜거나 끕니다."
L["List your profiles, or save the current settings as a new profile."] = "프로필 목록을 보거나 현재 설정을 새 프로필로 저장합니다."
L["Load one of your saved profiles."] = "저장된 프로필 중 하나를 불러옵니다."
L["Delete one of your saved profiles. Repeat the command to confirm."] = "저장된 프로필을 삭제합니다. 확인하려면 명령어를 한 번 더 입력하세요."
L["Reset all frame positions and visibility to the defaults."] = "모든 프레임 위치와 표시 여부를 기본값으로 되돌립니다."
L["Reset every setting in the active profile back to the defaults."] = "활성 프로필의 모든 설정을 기본값으로 되돌립니다."
L["Delete every MSUF profile and setting on this account."] = "이 계정의 모든 MSUF 프로필과 설정을 삭제합니다."
L["Turn the Wago Analytics beta telemetry on or off."] = "Wago Analytics 베타 원격 측정을 켜거나 끕니다."
L["Debug the group-frame hover and tooltip paths."] = "공격대 프레임의 마우스 오버 및 툴팁 경로를 디버그합니다."
L["Print the keyboard-capture frames for movement-lock diagnosis."] = "이동 잠김 진단을 위해 키보드를 가로채는 프레임을 출력합니다."
L["Toggle MSUF Edit Mode. Add a unit such as player or target to open it there."] = "MSUF 편집 모드를 전환합니다. player 나 target 같은 대상을 붙이면 해당 프레임에서 시작합니다."
L["Leave MSUF Edit Mode."] = "MSUF 편집 모드를 종료합니다."
L["Search the options menu and open the matching settings."] = "설정 메뉴를 검색해 일치하는 항목을 엽니다."
L["Start or resume the guided setup."] = "가이드 설정을 시작하거나 이어서 진행합니다."
L["Report how much of the current language is translated."] = "현재 언어의 번역 진행률을 알려줍니다."
L["Fake an available update to test the version-check popup."] = "버전 확인 알림을 시험하기 위해 업데이트가 있는 것처럼 처리합니다."
L["Replay the first-start flow or the upgrade highlights."] = "첫 실행 화면이나 업데이트 하이라이트를 다시 봅니다."
L["Profile which events drive the group frames in combat."] = "전투 중 공격대 프레임을 구동하는 이벤트를 프로파일링합니다."
L["Dump the aura frame levels for a layering bug report."] = "겹침 문제 제보용으로 오라 프레임 레벨을 출력합니다."
L["Check the options menu for structural problems."] = "설정 메뉴의 구조적 문제를 점검합니다."
L["Toggle the position drift debugger."] = "위치 밀림 디버거를 전환합니다."
L["  Profile: %s (%d saved)"] = "  프로필: %s (저장됨 %d개)"
L["  Edit Mode: %s - In combat: %s"] = "  편집 모드: %s - 전투 중: %s"
L["|cffff0000MSUF:|r The profile module is not loaded."] = "|cffff0000MSUF:|r 프로필 모듈이 불러와지지 않았습니다."
L["|cff00b7ebMSUF|r profiles:"] = "|cff00b7ebMSUF|r 프로필:"
L["  /msuf load <name> switches profile, /msuf profile <name> saves a new one."] = "  /msuf load <name> 은 프로필을 전환하고, /msuf profile <name> 은 새로 저장합니다."
L["|cffff0000MSUF:|r Cannot change profiles while in combat."] = "|cffff0000MSUF:|r 전투 중에는 프로필을 바꿀 수 없습니다."
L["|cffffcc00MSUF:|r Usage: /msuf load <name>. Type /msuf profile to list them."] = "|cffffcc00MSUF:|r 사용법: /msuf load <name>. 목록은 /msuf profile 로 확인하세요."
L["|cffff0000MSUF:|r '%s' matches more than one profile. Type the full name."] = "|cffff0000MSUF:|r '%s' 과(와) 일치하는 프로필이 여러 개입니다. 전체 이름을 입력하세요."
L["|cffff0000MSUF:|r Unknown profile '%s'. Type /msuf profile to list them."] = "|cffff0000MSUF:|r 알 수 없는 프로필 '%s'. 목록은 /msuf profile 로 확인하세요."
L["|cffffd700MSUF:|r Profile '%s' is already active."] = "|cffffd700MSUF:|r 프로필 '%s' 은(는) 이미 사용 중입니다."
L["|cffffcc00MSUF:|r Usage: /msuf delete <name>. Type /msuf profile to list them."] = "|cffffcc00MSUF:|r 사용법: /msuf delete <name>. 목록은 /msuf profile 로 확인하세요."
L["|cffffcc00MSUF:|r Repeat |cffffff00/msuf delete %s|r to delete that profile for good."] = "|cffffcc00MSUF:|r 해당 프로필을 완전히 삭제하려면 |cffffff00/msuf delete %s|r 를 다시 입력하세요."
L["|cffff0000MSUF:|r Cannot reset a profile while in combat."] = "|cffff0000MSUF:|r 전투 중에는 프로필을 초기화할 수 없습니다."
L["|cffffcc00MSUF:|r This resets every setting in profile '%s', not just positions."] = "|cffffcc00MSUF:|r 프로필 '%s' 의 위치뿐 아니라 모든 설정이 초기화됩니다."
L["|cffffcc00MSUF:|r Type |cffffff00/msuf default confirm|r to go ahead."] = "|cffffcc00MSUF:|r 계속하려면 |cffffff00/msuf default confirm|r 을 입력하세요."
L["|cffffcc00MSUF:|r Type |cffffff00/msuf default|r first, then confirm it."] = "|cffffcc00MSUF:|r 먼저 |cffffff00/msuf default|r 를 입력한 뒤 확인하세요."
L["|cffff0000MSUF:|r Unknown frame '%s'. Try player, target, focus, pet, boss or priority."] = "|cffff0000MSUF:|r 알 수 없는 프레임 '%s'. player, target, focus, pet, boss, priority 중에서 입력하세요."
L["|cffffd700MSUF:|r MSUF Edit Mode is not running."] = "|cffffd700MSUF:|r MSUF 편집 모드가 실행 중이 아닙니다."
L["Help unavailable"] = "도움말을 사용할 수 없음"
L["General"] = "일반"
L["Diagnostics"] = "진단"
L["|cffff0000MSUF:|r Cannot change absorb bars while in combat."] = "|cffff0000MSUF:|r 전투 중에는 흡수량 바를 바꿀 수 없습니다."

--- Castbar icon layer (6.0 Beta 29)
L["0 keeps the icon just above the bar and moves it together with the whole-castbar layer. 1-30 pins the icon to that frame level on the shared layer scale, so it can be ordered in front of or behind the bar, texts, and other frame elements."] = "0은 아이콘을 바 바로 위에 유지하고 시전 바 전체 레이어와 함께 이동합니다. 1-30은 아이콘을 공유 레이어 첩도의 해당 프레임 레벨에 고정하여 바, 글자, 다른 프레임 요소의 앞이나 뒤로 정렬할 수 있습니다."

