L["Animate"] = "애니메이션"
L["Lock zoom"] = "확대/축소 고정"
L["Locked: the preview keeps this zoom and position when you toggle layers."] = "고정됨: 레이어를 전환해도 미리보기가 현재 확대/축소와 위치를 유지합니다."
L["Unlocked: the preview refits itself whenever the frame footprint changes."] = "해제됨: 프레임 크기가 바뀔 때마다 미리보기가 다시 맞춰집니다."
