L["Preview element"] = "미리보기 요소"
L["Jumps to the options section that owns the selected preview element."] = "선택한 미리보기 요소를 담당하는 설정 구역으로 이동합니다."
L["Puts the selected element back to its default X/Y offset."] = "선택한 요소를 기본 X/Y 위치 값으로 되돌립니다."
