L["Lists every element the preview placed, including those hidden behind another handle. Tab and Shift+Tab step through the same list."] = "미리보기가 배치한 모든 요소를 표시하며, 다른 핸들에 가려진 요소도 포함합니다. Tab과 Shift+Tab으로 같은 목록을 이동합니다."
L["drag to move - Tab picks the next element - ? lists every control"] = "드래그로 이동 - Tab으로 다음 요소 선택 - ?로 모든 조작 보기"
L["guides hidden - arrows still nudge the selected element"] = "안내선 숨김 - 방향키로 선택한 요소를 계속 이동할 수 있습니다"
