L["The shown colors follow the selected indicator style."] = "표시되는 색상은 선택한 표시기 스타일을 따릅니다."
L["These colors are shared from the Colors page."] = "이 색상은 색상 페이지에서 공유됩니다."
L["Used when melee-range coloring is enabled."] = "근접 사거리 색상 표시가 켜져 있을 때 사용됩니다."
L["Used by the Castbar icon-border style."] = "시전 바의 아이콘 테두리 스타일에서 사용합니다."
L["Used only when the power bar is detached from the frame."] = "자원 바가 프레임에서 분리된 경우에만 사용됩니다."
L["Outline and fill behavior."] = "외곽선과 채우기 동작입니다."
L["Opacity values used by range and offline states."] = "사거리 및 오프라인 상태에서 사용하는 불투명도 값입니다."
L["Width can use manual bounds or follow another frame."] = "너비는 수동 범위를 쓰거나 다른 프레임을 따를 수 있습니다."
L["Power textures live on the Bars page."] = "자원 텍스처는 바 페이지에 있습니다."
L["When anchored here, Player power settings are managed by Class Resources."] = "여기에 고정하면 플레이어 자원 설정은 직업 자원에서 관리합니다."
L["Font face follows Shared; text and color mode mirror Player HP."] = "글꼴은 공용을 따르고, 텍스트와 색상 모드는 플레이어 생명력을 그대로 사용합니다."
L["Local HP text uses shared face settings and a fixed white color."] = "로컬 생명력 텍스트는 공용 글꼴 설정과 고정된 흰색을 사용합니다."
L["Synchronized with Text Colors in the Fonts menu for this scope."] = "이 범위의 글꼴 메뉴에 있는 텍스트 색상과 동기화됩니다."
L["Open the shared font and colors used by every Aura scope."] = "모든 오라 범위가 사용하는 공용 글꼴과 색상을 엽니다."
L["Tints unit-frame health bars when a configured debuff condition is active."] = "설정한 디버프 조건이 활성일 때 유닛 프레임 생명력 바에 색을 입힙니다."
L["Shows a symbol naming the dispel type of an active debuff."] = "활성 디버프의 해제 유형을 나타내는 기호를 표시합니다."
L["Shows the raid subgroup number from the raid roster."] = "공격대 명단의 소그룹 번호를 표시합니다."
L["Shows the raid subgroup number. Party frames only display it while you are in an actual raid group."] = "공격대 소그룹 번호를 표시합니다. 파티 프레임은 실제 공격대에 있을 때만 표시합니다."
L["Independent of mouseover. Marks your current target in the selected group-frame types."] = "마우스 오버와 무관합니다. 선택한 그룹 프레임 유형에서 현재 대상을 표시합니다."
L["Configure target highlighting in Appearance > Miscellaneous > Frame Highlights."] = "대상 강조는 모양 > 기타 > 프레임 강조에서 설정하세요."
L["Configure the color used by the Solid and Custom portrait border styles."] = "단색 및 맞춤 초상화 테두리 스타일에 사용할 색상을 설정합니다."
L["Configure the optional portrait background color."] = "선택적인 초상화 배경 색상을 설정합니다."
L["Configure the Party portrait border color and opacity."] = "파티 초상화 테두리의 색상과 불투명도를 설정합니다."
L["Scales frame size, fonts, and icons proportionally."] = "프레임 크기, 글꼴, 아이콘을 비례적으로 조정합니다."
L["Buff/debuff positions stay relative to their anchors."] = "버프/디버프 위치는 각 기준점에 상대적으로 유지됩니다."
L["Automatically scale by group size."] = "그룹 크기에 따라 자동으로 크기를 조정합니다."
L["Drag rows with mouse to reorder."] = "마우스로 행을 끌어 순서를 바꾸세요."
