L["Ask MSUF below and it will guide you to the right option."] = "아래에서 MSUF에게 물어보면 알맞은 옵션으로 안내합니다."
L["You can choose the Complete Tour on the next screen. A restore point is saved first."] = "다음 화면에서 전체 둘러보기를 선택할 수 있습니다. 먼저 복원 지점이 저장됩니다."
L["MISSION COMPLETE - Press Finish to open the Assistant on your Dashboard."] = "임무 완료 - 완료를 누르면 대시보드에서 어시스턴트가 열립니다."
