L["Color for the selected text indicator. Right-click to follow the frame font color again."] = "선택한 텍스트 표시기의 색상입니다. 마우스 오른쪽 버튼을 클릭하면 프레임 글꼴 색상을 다시 따릅니다."
L["Castbar text follows the shared Fonts settings until this text gets its own color."] = "시전 바 텍스트는 자체 색상이 지정될 때까지 공유 글꼴 설정을 따릅니다."
L["Font style follows the Fonts menu for this frame; the color can be set per indicator."] = "글꼴 스타일은 이 프레임의 글꼴 메뉴를 따르며, 색상은 표시기별로 지정할 수 있습니다."
L["Each castbar text can override the shared castbar text color. Target text exists on Target and Focus only."] = "각 시전 바 텍스트는 공유 색상을 덮어쓸 수 있습니다. 대상 텍스트는 대상과 주시 대상에만 있습니다."
L["Color for a single text indicator on one frame. Unset indicators follow that frame's font color."] = "한 프레임의 텍스트 표시기 하나에 대한 색상입니다. 색상이 없으면 표시기는 프레임 글꼴 색상을 따릅니다."
L["Aura Style > Defensive Buffs can follow the frame portrait shape."] = "오라 스타일 > 방어 버프는 프레임 초상화 모양을 따를 수 있습니다."
L["Cooldown timer urgency plus shared icon border and shadow colors."] = "쿨다운 타이머 긴급도와 공유 아이콘 테두리 및 그림자 색상입니다."
L["Follow shared settings"] = "공유 설정 따르기"
L["Icon Shape"] = "아이콘 모양"
L["Keeps Icon Shape synchronized with Aura Style > Shared while the remaining Group Aura settings stay local."] = "아이콘 모양을 오라 스타일 > 공유와 동기화하고 나머지 그룹 오라 설정은 개별로 유지합니다."
L["Shared icon shape"] = "공유 아이콘 모양"
L["Visibility modes apply only to unit and group frames. Aura tooltips use their own Show Tooltip switches; even Never does not override them. Auras only reuse the selected Blizzard/MSUF look and cursor placement."] = "표시 모드는 유닛 및 그룹 프레임에만 적용됩니다. 오라 툴팁은 자체 툴팁 표시 설정을 사용하며 절대로를 선택해도 이를 덮어쓰지 않습니다. 오라는 선택한 Blizzard/MSUF 모양과 커서 위치만 따릅니다."
L["Applies to the entire castbar: bar, icon, all text, effects, and border. All MSUF elements share this 0-30 order; every part of layer 30 draws above every part of layer 29."] = "시전 바 전체에 적용됩니다: 바, 아이콘, 모든 텍스트, 효과, 테두리. 모든 MSUF 요소가 이 0-30 순서를 공유하며, 레이어 30의 모든 부분은 레이어 29의 모든 부분 위에 그려집니다."
L["Display: "] = "표시: "
