--- Blizzard Raid Manager visibility (Group Frames > Layout > Frame Basics)
L["Always hidden"] = "항상 숨김"
L["Blizzard Raid Manager"] = "블리자드 공격대 관리자"
L["Blizzard's tab at the left screen edge with ready check, raid markers, and role filters. One shared frame, so this setting is the same for Party, Raid, and Mythic Raid."] = "준비 확인, 공격대 표식, 역할 필터가 있는 화면 왼쪽 가장자리의 블리자드 탭입니다. 하나의 공유 프레임이므로 이 설정은 파티, 공격대, 신화 공격대에서 동일하게 적용됩니다."
L["Fades the Raid Manager out until the mouse touches it. Ready check, raid markers, and role filters stay reachable, and an expanded panel stays visible until you collapse it again."] = "마우스를 올릴 때까지 공격대 관리자를 숨깁니다. 준비 확인, 공격대 표식, 역할 필터는 계속 사용할 수 있으며, 펌친 창은 다시 접을 때까지 표시된 상태로 유지됩니다."
L["Keeps the Raid Manager invisible and click-through at all times. Switch back to reach its buttons again."] = "공격대 관리자를 항상 보이지 않게 하고 클릭도 통과시킵니다. 버튼을 다시 사용하려면 설정을 되돌리십시오."
L["Show on mouseover"] = "마우스 오버 시 표시"
L["Automatic"] = "자동"
L["Always visible"] = "항상 표시"
L["Hides the Raid Manager while MSUF provides the live group frames, and leaves it to WoW otherwise. This is how MSUF has always behaved."] = "MSUF가 활성 그룹 프레임을 제공하는 동안에는 공격대 관리자를 숨기고, 그 외에는 WoW에 맡깁니다. MSUF는 지금까지 항상 이렇게 동작했습니다."
L["Keeps the Raid Manager reachable even with MSUF group frames on. Use this when you still want its ready check, raid markers, and role filters."] = "MSUF 그룹 프레임을 사용하는 중에도 공격대 관리자를 계속 사용할 수 있게 합니다. 준비 확인, 공격대 표식, 역할 필터가 여전히 필요할 때 선택하십시오."
L["Shared by Party, Raid, and Mythic Raid. Automatic keeps the tab hidden while MSUF provides the group frames."] = "파티, 공격대, 신화 공격대가 함께 사용합니다. 자동은 MSUF가 그룹 프레임을 제공하는 동안 탭을 숨겨 둡니다."
L["MSUF detected %s."] = "MSUF detected %s."
L["Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"] = "Would you like MSUF to anchor the global Unit Frame layout to Essential Cooldown Manager?"
L["Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."] = "Nothing will move unless you confirm again in the next step. You can change this later in MSUF Edit Mode."
L["Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."] = "Nothing will move unless you confirm again in the next step. If you choose Keep independent, you can enable CDM anchoring at any time in MSUF Edit Mode or under Unit > Anchoring in the MSUF menu."
L["Second confirmation for %s."] = "Second confirmation for %s."
L["MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."] = "MSUF will now anchor the global Unit Frame layout to Essential Cooldown Manager."
L["Confirm only if you want the whole Unit Frame layout to move with your cooldowns."] = "Confirm only if you want the whole Unit Frame layout to move with your cooldowns."
L["Confirm anchoring"] = "Confirm anchoring"
L["Continue"] = "Continue"
L["Keep independent"] = "Keep independent"
L["%s detected: Global anchor follows Essential Cooldown Manager. Toggle Cooldown in MSUF Edit Mode to turn it off."] = "%s 감지됨: 전역 앵커가 중요 재사용 대기시간 관리자를 따릅니다. MSUF 편집 모드의 Cooldown으로 끌 수 있습니다."
L["%s detected: Cooldown Manager anchoring is off. Toggle Cooldown in MSUF Edit Mode to turn it on."] = "%s 감지됨: 재사용 대기시간 관리자 앵커가 꺼져 있습니다. MSUF 편집 모드의 Cooldown으로 켤 수 있습니다."
L["Cooldown Manager anchoring (%s)"] = "재사용 대기시간 관리자 고정 (%s)"
L["Global anchor (%s Anchor)"] = "전역 앵커 (%s 앵커)"
L["Fades all four outer edges; 0% keeps the original texture."] = "바깥쪽 네 가장자리를 모두 흐리게 합니다. 0%는 원본 텍스처를 유지합니다."

-- Menu localization pass 2026-08-06: previously untranslated menu strings.
L["1:1 shows the configured aura pixel size."] = "1:1은 설정된 오라 픽셀 크기를 표시합니다."
L["Aura Options"] = "오라 옵션"
L["Aura Options and Aura Style belong to this UnitFrame. Global icon appearance: Appearance > Aura Style."] = "오라 옵션과 오라 스타일은 이 UnitFrame에 속합니다. 전역 아이콘 외관: 외관 > 오라 스타일."
L["Below this value, remaining whole seconds may show one decimal place. Set 0 for whole seconds only."] = "이 값보다 짧게 남으면 소수점 한 자리까지 표시됩니다. 0으로 설정하면 정수 초만 표시합니다."
L["Buff Appearance"] = "버프 외관"
L["Debuff Appearance"] = "디버프 외관"
L["Global Aura Appearance: Buffs"] = "전역 오라 외관: 버프"
L["Global Aura Appearance: Debuffs"] = "전역 오라 외관: 디버프"
L["Timer colors are shared by live unit/group auras and every preview. Icon border and shadow colors live in Appearance > Auras, scoped by Aura type."] = "타이머 색상은 실시간 유닛/그룹 오라와 모든 미리보기에 공통으로 적용됩니다. 아이콘 테두리와 그림자 색상은 외관 > 오라에서 오라 유형별로 설정합니다."
L["Click to open the setting that enables this layer."] = "이 레이어를 활성화하는 설정을 열려면 클릭하십시오."
L["Controls native Aura tooltips for Spell Icons only."] = "주문 아이콘에만 적용되는 기본 오라 툴팁을 제어합니다."
L["Cooldown text format"] = "재사용 대기시간 텍스트 형식"
L["Copies Buff, Debuff, External Defensive and Spell Icon presentation, including icon zoom, text, swipe, duration bars and ordering. Aura Options, tracked Spell Icons and the global Appearance theme remain unchanged."] = "아이콘 확대, 텍스트, 쓸어내기, 지속시간 바, 정렬을 포함하여 버프, 디버프, 외부 방어 효과, 주문 아이콘의 표시 방식을 복사합니다. 오라 옵션, 추적 중인 주문 아이콘, 전역 외관 테마는 변경되지 않습니다."
L["Copies Group Aura visibility, layout, filters, exact/category blacklists, Strata and dispel options. Aura Style and the global Appearance theme remain unchanged."] = "공격대 오라의 표시 여부, 레이아웃, 필터, 정확/분류 블랙리스트, 프레임 계층, 해제 옵션을 복사합니다. 오라 스타일과 전역 외관 테마는 변경되지 않습니다."
L["Copies this UnitFrame's Aura visibility, layout, filters, blacklists, Custom Aura setup and tracked spells. Aura Style and the global Appearance theme remain unchanged."] = "이 UnitFrame의 오라 표시 여부, 레이아웃, 필터, 블랙리스트, 사용자 지정 오라 구성, 추적 주문을 복사합니다. 오라 스타일과 전역 외관 테마는 변경되지 않습니다."
L["Copies this UnitFrame's Buff, Debuff, Custom Aura, Player Defensive and Dots on Target presentation, including text, swipe, icon zoom, duration bars, Pandemic and Full-Frame effects. Aura Options and the global Appearance theme remain unchanged."] = "텍스트, 쓸어내기, 아이콘 확대, 지속시간 바, 판데믹, 전체 프레임 효과를 포함하여 이 UnitFrame의 버프, 디버프, 사용자 지정 오라, 플레이어 방어 효과, 대상 DoT의 표시 방식을 복사합니다. 오라 옵션과 전역 외관 테마는 변경되지 않습니다."
L["Drag background (%dx)"] = "배경 끌기 (%dx)"
L["Drag to move. Arrow keys nudge."] = "끌어서 이동합니다. 방향키로 미세 조정합니다."
L["EllesmereUI"] = "EllesmereUI"
L["EllesmereUI Unlock Mode"] = "EllesmereUI 잠금 해제 모드"
L["Exact X coordinate"] = "정확한 X 좌표"
L["Exact Y coordinate"] = "정확한 Y 좌표"
L["Fit shows the complete aura layout."] = "맞춤은 전체 오라 레이아웃을 표시합니다."
L["Global Appearance theme selected only by Aura type. All layout, filters, timers, text and effects stay scope-aware in the corresponding UnitFrame or GroupFrame."] = "전역 외관 테마는 오라 종류로만 선택합니다. 레이아웃, 필터, 타이머, 텍스트, 효과는 해당 UnitFrame 또는 GroupFrame의 범위를 그대로 따릅니다."
L["Individual Style is edited here. Shared icon theme: Appearance > Aura Style."] = "개별 스타일은 여기에서 편집합니다. 공유 아이콘 테마: 외관 > 오라 스타일."
L["Layout, filters, lists and every container-specific Style live in each frame. Appearance > Aura Style owns only the global icon theme."] = "레이아웃, 필터, 목록, 컨테이너별 스타일은 각 프레임에 있습니다. 외관 > 오라 스타일은 전역 아이콘 테마만 관리합니다."
L["Measured from the center of the previewed frame. Positive values move right. Arrow keys and dragging update the same position."] = "미리보기 프레임의 중앙을 기준으로 측정합니다. 양수 값은 오른쪽으로 이동합니다. 방향키와 끌기는 같은 위치 값을 갱신합니다."
L["Measured from the center of the previewed frame. Positive values move up. Arrow keys and dragging update the same position."] = "미리보기 프레임의 중앙을 기준으로 측정합니다. 양수 값은 위쪽으로 이동합니다. 방향키와 끌기는 같은 위치 값을 갱신합니다."
L["On (default): MSUF frames appear in EllesmereUI Unlock Mode. Turn this off to keep using the native MSUF Edit Mode. MSUF profile positions remain the source of truth."] = "켜짐(기본값): MSUF 프레임이 EllesmereUI 잠금 해제 모드에 표시됩니다. 이 옵션을 끄면 MSUF 자체 편집 모드를 계속 사용합니다. MSUF 프로필 위치가 항상 기준입니다."
L["Open the frame and expand Auras. Buffs and Debuffs contain their own layout, filters, blacklists and Style; Custom 1-3, Defensive Buffs and Dots on target expose controls appropriate to their content."] = "프레임을 열고 오라를 펼치십시오. 버프와 디버프에는 각자의 레이아웃, 필터, 블랙리스트, 스타일이 있으며 사용자 지정 1-3, 방어 버프, 대상 DoT는 각 내용에 맞는 설정을 제공합니다."
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This GroupFrame's individual Style stays here."] = "전역 오라 아이콘 테마를 엽니다: 테두리, 그림자, 색상, 줄 여백, 플레이어 무기 마법부여. 이 GroupFrame의 개별 스타일은 여기에 남아 있습니다."
L["PERFORMANCE WARNING (12.1): Blizzard can run an OnUpdate every frame on each visible aura button for the full aura while it has a calculated pandemic window, not only while the warning is shown. Enable only if you accept this potentially high combat cost."] = "성능 경고 (12.1): 오라에 계산된 판데믹 구간이 있는 동안에는 경고가 표시될 때뿐만 아니라, Blizzard가 보이는 모든 오라 버튼에 대해 매 프레임 OnUpdate를 실행할 수 있습니다. 전투 중 발생할 수 있는 높은 비용을 감수할 경우에만 활성화하십시오."
L["Paints a stand-in tint on the live GroupFrames so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "실제로 해제 가능한 디버프 없이도 오버레이를 확인할 수 있도록 활성 GroupFrames에 임시 색조를 입힙니다. 이 페이지를 닫으면 자동으로 꺼집니다."
L["Paints a stand-in tint on the live UnitFrame so the overlay can be judged without a real dispellable debuff. Turns itself off when this page closes."] = "실제로 해제 가능한 디버프 없이도 오버레이를 확인할 수 있도록 활성 UnitFrame에 임시 색조를 입힙니다. 이 페이지를 닫으면 자동으로 꺼집니다."
L["Position is controlled by the colored aura handle in Preview."] = "위치는 미리보기의 색상 오라 손잡이로 조정합니다."
L["Preview position"] = "미리보기 위치"
L["Runtime Preview"] = "실시간 미리보기"
L["Runtime Preview: live GroupFrames"] = "실시간 미리보기: 활성 GroupFrames"
L["Runtime Preview: live UnitFrame"] = "실시간 미리보기: 활성 UnitFrame"
L["Runtime Preview: live UnitFrame (drag)"] = "실시간 미리보기: 활성 UnitFrame (끌기)"
L["Shape, border and shadow: Appearance > Aura Style > Buffs. All controls here remain Group-scope aware."] = "모양, 테두리, 그림자: 외관 > 오라 스타일 > 버프. 여기의 모든 설정은 공격대 범위를 그대로 따릅니다."
L["Shared Aura Style"] = "공유 오라 스타일"
L["Shared Aura Style: Buffs"] = "공유 오라 스타일: 버프"
L["Shared Aura Style: Debuffs"] = "공유 오라 스타일: 디버프"
L["Shared Preview - "] = "공유 미리보기 - "
L["Shows stand-in symbols on the live UnitFrame and lets you drag them into position without a real debuff. Turns itself off when this page closes."] = "활성 UnitFrame에 임시 기호를 표시하여 실제 디버프 없이도 원하는 위치로 끌 수 있게 합니다. 이 페이지를 닫으면 자동으로 꺼집니다."
L["Spell Icon Style"] = "주문 아이콘 스타일"
L["Spell Icon tooltip"] = "주문 아이콘 툴팁"
L["Swipe Direction"] = "쓸어내기 방향"
L["This switch is shown only while EllesmereUI is loaded. Disabling it immediately returns MSUF to its own Edit Mode."] = "이 설정은 EllesmereUI가 로드된 동안에만 표시됩니다. 끄는 즉시 MSUF는 자체 편집 모드로 돌아갑니다."
L["Use - / + or Ctrl + mouse wheel to zoom."] = "- / + 또는 Ctrl + 마우스 휠로 확대하십시오."
L["Use EllesmereUI Unlock Mode for MSUF"] = "MSUF에 EllesmereUI 잠금 해제 모드 사용"
L["Use the colored Texture handle in Preview for exact placement."] = "정확한 배치를 위해 미리보기의 색상 텍스처 손잡이를 사용하십시오."
L["Zoom changes only this preview, not your Aura settings."] = "확대는 이 미리보기에만 적용되며 오라 설정은 변경되지 않습니다."

-- Menu localization pass 2026-08-06 (part 2): dropdown values, tooltips and labels routed through Tr() that the coverage extractor could not see.
L["+ Value"] = "+ 값"
L["1 px"] = "1 px"
L["12.1 Pandemic state"] = "12.1 판데믹 상태"
L["2 px"] = "2 px"
L["Absorb (negative)"] = "흡수 (음수)"
L["Absorb (positive)"] = "흡수 (양수)"
L["Add enemy debuff"] = "적 디버프 추가"
L["Add entire set"] = "전체 세트 추가"
L["Add spell"] = "주문 추가"
L["Adds Blizzard's temporary weapon-enchantment buttons to the Player Buff container. This is one shared setting and uses the native aura flow without an MSUF ticker or OnUpdate."] = "Blizzard의 임시 무기 마법부여 버튼을 플레이어 버프 컨테이너에 추가합니다. 하나의 공유 설정이며 MSUF 티커나 OnUpdate 없이 기본 오라 흐름을 사용합니다."
L["Adds an exact harmful aura ID that is missing from the curated list. The aura is still restricted to your current target and your own aura source."] = "선별 목록에 없는 정확한 해로운 오라 ID를 추가합니다. 해당 오라는 여전히 현재 대상과 본인이 시전한 오라로 제한됩니다."
L["Adds one exact buff to this frame's blacklist."] = "정확한 버프 하나를 이 프레임의 블랙리스트에 추가합니다."
L["Adds one exact buff to this group's blacklist."] = "정확한 버프 하나를 이 공격대의 블랙리스트에 추가합니다."
L["Adds one exact harmful aura to this Target, Focus, or Boss blacklist. Blizzard applies arbitrary SpellID filters only while the unit is not assistable."] = "정확한 해로운 오라 하나를 이 대상, 주시 대상 또는 우두머리 블랙리스트에 추가합니다. Blizzard는 해당 유닛을 도울 수 없는 동안에만 임의의 SpellID 필터를 적용합니다."
L["All Buffs"] = "모든 버프"
L["All Debuffs"] = "모든 디버프"
L["All roles"] = "모든 역할"
L["Always excludes auras without a duration, even when Blizzard token filters are disabled."] = "Blizzard 토큰 필터가 꺼져 있어도 지속시간이 없는 오라를 항상 제외합니다."
L["Always excludes auras without a duration."] = "지속시간이 없는 오라를 항상 제외합니다."
L["Always excludes auras without a duration. It remains active when token filters are disabled."] = "지속시간이 없는 오라를 항상 제외합니다. 토큰 필터가 꺼져 있어도 계속 적용됩니다."
L["Always excludes auras without a duration. This native rule wins over SpellID blacklists and whitelists."] = "지속시간이 없는 오라를 항상 제외합니다. 이 기본 규칙은 SpellID 블랙리스트와 화이트리스트보다 우선합니다."
L["Anchor To Class Resource"] = "직업 자원에 고정"
L["Any Dispel Type"] = "모든 해제 유형"
L["Any dispel type"] = "모든 해제 유형"
L["Applicable by Me (Raid)"] = "내가 적용 가능 (공격대)"
L["Applies to every UnitFrame and GroupFrame icon of this Aura type. Spell Icons use the Buff appearance."] = "이 오라 종류의 모든 UnitFrame 및 GroupFrame 아이콘에 적용됩니다. 주문 아이콘은 버프 외관을 사용합니다."
L["Aura sort order"] = "오라 정렬 순서"
L["Aura sorting"] = "오라 정렬"
L["Aura tooltip"] = "오라 툴팁"
L["Auto breakpoints"] = "자동 중단점"
L["Auto fit"] = "자동 맞춤"
L["Auto fit pips"] = "칸 자동 맞춤"
L["Auto-blacklist from Debuffs"] = "디버프에서 자동 제외"
L["Auto-blacklist from player buffs"] = "플레이어 버프에서 자동 제외"
L["Auto: Essential Cooldowns"] = "자동: 필수 재사용 대기시간"
L["Auto: Unit Frame"] = "자동: 유닛 프레임"
L["Auto: Utility Cooldowns"] = "자동: 보조 재사용 대기시간"
L["Bar Only hides the aura icon. Icon + Bar keeps the icon and draws the duration bar on it."] = "바만은 오라 아이콘을 숨깁니다. 아이콘 + 바는 아이콘을 유지하고 그 위에 지속시간 바를 그립니다."
L["Bar keeps the normal statusbar. Follow Player Power mirrors the independent detached Player power shape. Orb uses a single vertical fill."] = "바는 일반 상태바를 유지합니다. 플레이어 자원 따르기는 분리된 플레이어 자원의 모양을 그대로 따릅니다. 구슬은 하나의 세로 채우기를 사용합니다."
L["Big Defensive"] = "대형 방어 효과"
L["Big Defensive Player"] = "대형 방어 효과 (플레이어)"
L["Blizzard castbar"] = "Blizzard 시전 바"
L["Blizzard ring + symbol"] = "Blizzard 고리 + 기호"
L["Blizzard symbol"] = "Blizzard 기호"
L["Blocks every aura in the selected curated MSUF set."] = "선택한 MSUF 선별 세트의 모든 오라를 차단합니다."
L["Blocks only the selected aura from the curated set."] = "선별 세트에서 선택한 오라만 차단합니다."
L["Cancelable Player"] = "취소 가능 (플레이어)"
L["Castbar Border"] = "시전 바 테두리"
L["Changes only the detached Player Powerbar. Class Resource shape on the left changes only Class Resources."] = "분리된 플레이어 자원 바만 변경합니다. 왼쪽의 직업 자원 모양은 직업 자원만 변경합니다."
L["Class Resource Preview"] = "직업 자원 미리보기"
L["Class Resource and Player Power follow existing frames. Custom uses the slider below. Width is resolved only during layout refresh."] = "직업 자원과 플레이어 자원은 기존 프레임을 따릅니다. 사용자 지정은 아래 슬라이더를 사용합니다. 너비는 레이아웃 갱신 시에만 결정됩니다."
L["Controls only the second HP bar outline. Bar uses four outside border edges; shapes use their fixed edge texture. 0 disables only the outline."] = "두 번째 생명력 바의 외곽선만 제어합니다. 바는 바깥쪽 네 개의 테두리를 사용하고, 도형은 고정된 가장자리 텍스처를 사용합니다. 0은 외곽선만 끕니다."
L["Controls only this second HP bar. The normal Player unitframe HP text remains separate."] = "이 두 번째 생명력 바만 제어합니다. 일반 플레이어 프레임의 생명력 텍스트는 별도로 유지됩니다."
L["Controls this aura lane independently. Always / Out of Combat / Modifier / Never under Global Style > Miscellaneous affect only unit and group frames. Auras only reuse the selected Blizzard/MSUF look and cursor placement."] = "이 오라 줄을 독립적으로 제어합니다. 전역 스타일 > 기타의 항상 / 비전투 중 / 보조키 / 사용 안 함은 유닛 및 공격대 프레임에만 적용됩니다. 오라는 선택한 Blizzard/MSUF 모양과 커서 위치만 재사용합니다."
L["Cooldown swipe direction"] = "재사용 대기시간 쓸어내기 방향"
L["Core feature enabled by default for new profiles and once for existing profiles. It works as a normal defensive buff bar without an enabled portrait. Turn this off to disable both bar and portrait-position display."] = "새 프로필에는 기본으로, 기존 프로필에는 한 번만 활성화되는 핵심 기능입니다. 초상화가 없어도 일반 방어 버프 바처럼 동작합니다. 이 옵션을 끄면 바와 초상화 위치 표시가 모두 비활성화됩니다."
L["Crowd Control"] = "군중 제어"
L["Curated Retail 12.0+ and 12.1 DoT auras. Tracking is restricted to this UnitFrame's unit and your own aura source; Boss settings bind separately to boss1 through boss5."] = "Retail 12.0+ 및 12.1용으로 선별한 DoT 오라입니다. 추적은 이 UnitFrame의 유닛과 본인이 시전한 오라로 제한되며, 우두머리 설정은 boss1부터 boss5까지 개별적으로 연결됩니다."
L["Custom Spell ID"] = "사용자 지정 주문 ID"
L["Dark Border"] = "어두운 테두리"
L["Disabled by default. Blizzard's native implementation enables a per-frame OnUpdate for each visible aura button as soon as that aura has a calculated pandemic window; this can begin before the warning becomes visible."] = "기본적으로 비활성화되어 있습니다. Blizzard의 기본 구현은 오라에 계산된 판데믹 구간이 생기는 즉시 보이는 모든 오라 버튼에 프레임 단위 OnUpdate를 활성화하며, 이는 경고가 표시되기 전에 시작될 수 있습니다."
L["Dispellable by Group"] = "공격대가 해제 가능"
L["Dispellable by Me (Raid)"] = "내가 해제 가능 (공격대)"
L["Dispellable by group"] = "공격대가 해제 가능"
L["Down (Single Column)"] = "아래로 (단일 열)"
L["Duration bar display"] = "지속시간 바 표시"
L["Duration bar fill mode"] = "지속시간 바 채우기 방식"
L["Duration bar position"] = "지속시간 바 위치"
L["Edge strength of every detached Player power shape, including Bar, Round, Crystal and Orb. 0 disables only that edge."] = "바, 원형, 수정, 구슬을 포함한 모든 분리형 플레이어 자원 모양의 가장자리 강도입니다. 0은 해당 가장자리만 끕니다."
L["Elapsed / Total"] = "경과 / 전체"
L["Enable defensive buffs"] = "방어 버프 활성화"
L["Enable tracked DoTs"] = "추적 DoT 활성화"
L["Enter a Spell ID, paste a spell link, or type a spell name. The visible helpful aura is matched even when its buff ID differs from the cast Spell ID."] = "주문 ID를 입력하거나 주문 링크를 붙여넣거나 주문 이름을 입력하십시오. 버프 ID가 시전한 주문 ID와 달라도 보이는 이로운 오라를 인식합니다."
L["Enter a Spell ID, paste a spell link, or type a spell name. This whitelist tracks exact Spell IDs."] = "주문 ID를 입력하거나 주문 링크를 붙여넣거나 주문 이름을 입력하십시오. 이 화이트리스트는 정확한 주문 ID를 추적합니다."
L["Essential cooldown viewer"] = "필수 재사용 대기시간 표시기"
L["Exact aura tracking"] = "정확한 오라 추적"
L["External Defensive"] = "외부 방어 효과"
L["External Defensive Player"] = "외부 방어 효과 (플레이어)"
L["Fill Mode"] = "채우기 방식"
L["Focus off"] = "주시 대상 끄기"
L["Focus on"] = "주시 대상 켜기"
L["Global follows the normal MSUF health color mode. Class Color forces your class color. Dark Mode forces the configured dark bar color. HP Gradient colors only this second HP bar by current health."] = "Global은 MSUF의 일반 생명력 색상 모드를 따릅니다. Class Color는 직업 색상을 강제합니다. Dark Mode는 설정된 어두운 바 색상을 강제합니다. HP Gradient는 이 두 번째 생명력 바만 현재 생명력에 따라 칠합니다."
L["Global icon shape"] = "전역 아이콘 모양"
L["HP Color"] = "생명력 색상"
L["HP Outline"] = "생명력 외곽선"
L["HP Shape"] = "생명력 바 모양"
L["HP only"] = "생명력만"
L["Healers only"] = "치유사만"
L["Hide permanent auras"] = "지속 오라 숨기기"
L["Hides this scope's selected DoT Spell IDs from the same UnitFrame's normal Debuff container while Dots on target is enabled. Blizzard's blacklist is SpellID-based, so the same spell cast by another player is hidden there too."] = "대상 DoT가 켜져 있는 동안 이 범위에서 선택한 DoT 주문 ID를 같은 UnitFrame의 일반 디버프 컨테이너에서 숨깁니다. Blizzard의 블랙리스트는 SpellID 기반이므로 다른 플레이어가 시전한 같은 주문도 함께 숨겨집니다."
L["Highest priority only"] = "최우선 순위만"
L["Icon Border & Shadow"] = "아이콘 테두리 및 그림자"
L["Include Nameplate-only"] = "이름표 전용 포함"
L["Inside Left"] = "안쪽 왼쪽"
L["Inside Right"] = "안쪽 오른쪽"
L["Keeps detached Player power attached to the Class Resource bar. Player power controls are disabled while this connection is active."] = "분리된 플레이어 자원을 직업 자원 바에 붙여 둡니다. 이 연결이 활성인 동안에는 플레이어 자원 설정이 비활성화됩니다."
L["Keeps the configured portrait size and position as an invisible anchor so the defensive icon can remain there while the portrait itself is disabled."] = "초상화 자체가 꺼져 있어도 방어 아이콘이 그 자리에 남을 수 있도록 설정된 초상화 크기와 위치를 보이지 않는 기준점으로 유지합니다."
L["Keeps the configured portrait size, position, and shape as an invisible anchor for tracked DoTs while the portrait itself is disabled."] = "초상화 자체가 꺼져 있어도 추적 DoT를 위해 설정된 초상화 크기, 위치, 모양을 보이지 않는 기준점으로 유지합니다."
L["Limits simultaneous DoT icons at the portrait from 1 to 8. Additional icons grow outward using this DoT lane's configured Growth direction."] = "초상화 위치의 동시 DoT 아이콘 수를 1~8개로 제한합니다. 추가 아이콘은 이 DoT 줄에 설정된 성장 방향으로 바깥쪽으로 늘어납니다."
L["Limits the number of simultaneous defensive icons at the portrait from 1 to 8. Existing profiles remain at 1 until this value is changed."] = "초상화 위치의 동시 방어 아이콘 수를 1~8개로 제한합니다. 기존 프로필은 이 값을 변경하기 전까지 1로 유지됩니다."
L["Lists every MSUF slash command in chat, diagnostics included."] = "진단 명령을 포함한 모든 MSUF 슬래시 명령어를 대화창에 표시합니다."
L["Max portrait icons"] = "최대 초상화 아이콘 수"
L["Maximum debuff duration"] = "최대 디버프 지속시간"
L["Moves all detached Player power text slots together. Slot X/Y controls below add per-slot offsets."] = "분리된 플레이어 자원의 모든 텍스트 칸을 함께 이동합니다. 아래의 칸별 X/Y 설정이 개별 위치 값을 더합니다."
L["Moves the Player power bar out of the unit frame. Anchor connects it to the Class Resources stack; Sync only follows the stack width."] = "플레이어 자원 바를 유닛 프레임 밖으로 옮깁니다. 고정은 직업 자원 묶음에 연결하고, 동기화는 묶음의 너비만 따릅니다."
L["Native Aura Flow"] = "기본 오라 흐름"
L["Blizzard Buff & Debuff Frames"] = "블리자드 강화 및 약화 효과 프레임"
L["Hide Blizzard Buff and Debuff Frames"] = "블리자드 강화 및 약화 효과 프레임 숨기기"
L["Hides only Blizzard's player Buff Frame and normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "미니맵 근처의 블리자드 플레이어 강화 효과 프레임과 일반 약화 효과 아이콘만 숨깁니다. 비공개 오라와 치명적인 약화 효과 경고는 계속 표시됩니다."
L["Buffs hidden"] = "강화 효과 숨김"
L["Buffs visible"] = "강화 효과 표시"
L["Debuffs hidden"] = "약화 효과 숨김"
L["Debuffs visible"] = "약화 효과 표시"
L["Hide Blizzard Buff Frame"] = "블리자드 강화 효과 프레임 숨기기"
L["Hide Blizzard Debuff Frame"] = "블리자드 약화 효과 프레임 숨기기"
L["Hides Blizzard's player Buff Frame near the minimap."] = "미니맵 근처의 블리자드 플레이어 강화 효과 프레임을 숨깁니다."
L["Hides only Blizzard's normal Debuff icons near the minimap. Private Auras and Deadly Debuff warnings remain visible."] = "미니맵 근처의 블리자드 일반 약화 효과 아이콘만 숨깁니다. 비공개 오라와 치명적인 약화 효과 경고는 계속 표시됩니다."
L["Native size"] = "기본 크기"
L["Native stealable marker"] = "기본 훔치기 가능 표시"
L["Native weapon enchant auras"] = "기본 무기 마법부여 오라"
L["No roles"] = "역할 없음"
L["No width limit"] = "너비 제한 없음"
L["Not Cancelable"] = "취소 불가"
L["Not Cancelable Player"] = "취소 불가 (플레이어)"
L["Off shows debuffs of any duration. Otherwise, debuffs whose total duration exceeds this number of seconds are hidden."] = "끄면 지속시간과 관계없이 모든 디버프를 표시합니다. 그렇지 않으면 총 지속시간이 이 초를 넘는 디버프가 숨겨집니다."
L["One per dispel type"] = "해제 유형별 하나"
L["Opens the global Aura icon theme: border, shadow, colors, lane padding and native Player weapon enchants. This frame's container Style stays here."] = "전역 오라 아이콘 테마를 엽니다: 테두리, 그림자, 색상, 줄 여백, 플레이어 무기 마법부여. 이 프레임의 컨테이너 스타일은 여기에 남아 있습니다."
L["Optional interpolation for this second HP bar. Off keeps direct native SetValue updates."] = "이 두 번째 생명력 바에 대한 선택적 보간입니다. 끄면 기본 SetValue 갱신을 직접 사용합니다."
L["Optional presentation mode; the Defensive Buffs feature itself does not require a portrait. With an enabled portrait, the first icon occupies it. When the portrait is off, enable the position option below to keep the icons there; otherwise MSUF safely falls back to the normal defensive bar."] = "선택적인 표시 방식이며, 방어 버프 기능 자체는 초상화를 요구하지 않습니다. 초상화가 켜져 있으면 첫 번째 아이콘이 그 자리를 차지합니다. 초상화가 꺼져 있을 때 아이콘을 그 자리에 두려면 아래 위치 옵션을 켜십시오. 그렇지 않으면 MSUF가 안전하게 일반 방어 바로 되돌아갑니다."
L["Orb Size"] = "구슬 크기"
L["Pandemic Warning & Style"] = "판데믹 경고 및 스타일"
L["Pandemic color"] = "판데믹 색상"
L["Places Player power text on the detached power bar. When off, the same Player power text remains positioned by the normal text layout."] = "플레이어 자원 텍스트를 분리된 자원 바 위에 배치합니다. 끄면 같은 텍스트가 일반 텍스트 레이아웃에 따라 배치됩니다."
L["Places the duration bar at the top or bottom edge of the aura slot."] = "지속시간 바를 오라 칸의 위쪽 또는 아래쪽 가장자리에 배치합니다."
L["Player Text Outline"] = "플레이어 텍스트 외곽선"
L["Power Bar Outline"] = "자원 바 외곽선"
L["Power Text On Bar"] = "바 위의 자원 텍스트"
L["Power anchors use the Player power bar when it is visible; otherwise the HP bar falls back to the Class Resource anchor."] = "자원 기준점은 플레이어 자원 바가 보일 때 이를 사용하고, 그렇지 않으면 생명력 바가 직업 자원 기준점으로 되돌아갑니다."
L["Raid In Combat"] = "전투 중 공격대"
L["Raid In Combat Player"] = "전투 중 공격대 (플레이어)"
L["Raid Player"] = "공격대 (플레이어)"
L["Remaining / Total"] = "남은 시간 / 전체"
L["Remaining shrinks as the aura expires. Elapsed grows until the aura expires."] = "남은 시간은 오라가 만료될수록 줄어듭니다. 경과는 오라가 만료될 때까지 늘어납니다."
L["Remaining time below this value uses one decimal place. Timers show unitless seconds below 1 minute and localized minutes above it. Set 0 for whole seconds only."] = "이 값보다 짧게 남으면 소수점 한 자리를 사용합니다. 타이머는 1분 미만에서는 단위 없는 초를, 그 이상에서는 현지화된 분을 표시합니다. 0으로 설정하면 정수 초만 표시합니다."
L["Remove from blacklist"] = "블랙리스트에서 제거"
L["Remove from whitelist"] = "화이트리스트에서 제거"
L["Renders a second native Player health bar. The normal Player unitframe HP bar is untouched, so you can show HP twice."] = "두 번째 기본 플레이어 생명력 바를 그립니다. 일반 플레이어 프레임의 생명력 바는 그대로 유지되므로 생명력을 두 번 표시할 수 있습니다."
L["Replaces the normal DoT lane with portrait-sized icons. The first icon exactly follows this frame's portrait width, height, and shape."] = "일반 DoT 줄을 초상화 크기의 아이콘으로 대체합니다. 첫 번째 아이콘은 이 프레임 초상화의 너비, 높이, 모양을 정확히 따릅니다."
L["Runs /msuf reset for frame positions and visibility."] = "프레임 위치와 표시 여부에 대해 /msuf reset을 실행합니다."
L["Second Player HP Bar"] = "두 번째 플레이어 생명력 바"
L["Sets the Player font scope used by detached Power text. Player Name and HP text share this outline setting."] = "분리된 자원 텍스트가 사용할 플레이어 글꼴 범위를 설정합니다. 플레이어 이름과 생명력 텍스트는 이 외곽선 설정을 공유합니다."
L["Show DoTs at portrait position"] = "초상화 위치에 DoT 표시"
L["Show buffs at portrait position"] = "초상화 위치에 버프 표시"
L["Show cooldown text on portrait"] = "초상화에 재사용 대기시간 텍스트 표시"
L["Shows the active defensive buff's remaining duration over its portrait icon. Blizzard updates the text natively."] = "활성 방어 버프의 남은 지속시간을 초상화 아이콘 위에 표시합니다. Blizzard가 텍스트를 기본적으로 갱신합니다."
L["Shows the selected class/spec resource below without changing your character, spec or saved settings."] = "캐릭터, 전문화, 저장된 설정을 변경하지 않고 선택한 직업/전문화 자원을 아래에 표시합니다."
L["Shows the tracked DoT's remaining duration over its portrait icon. Blizzard updates the duration natively."] = "추적 중인 DoT의 남은 지속시간을 초상화 아이콘 위에 표시합니다. Blizzard가 지속시간을 기본적으로 갱신합니다."
L["Simple presets for Player power text while detached power is managed by Class Resources. Custom Slots means the existing slot layout is kept until you choose a preset."] = "분리된 자원을 직업 자원이 관리하는 동안 사용할 플레이어 자원 텍스트의 간단한 사전 설정입니다. 사용자 지정 칸을 선택하면 사전 설정을 고를 때까지 기존 칸 배치가 유지됩니다."
L["Smooth Fill"] = "부드러운 채우기"
L["Spell Text"] = "주문 텍스트"
L["Stops blocking this aura."] = "이 오라의 차단을 해제합니다."
L["Sync Width"] = "너비 동기화"
L["Tanks only"] = "방어 전담만"
L["Target DoT"] = "대상 DoT"
L["Target off"] = "대상 끄기"
L["Target on"] = "대상 켜기"
L["Time Text"] = "시간 텍스트"
L["Track this predefined defensive buff. The setting applies to both the defensive bar and the optional portrait icon."] = "이 사전 정의된 방어 버프를 추적합니다. 이 설정은 방어 바와 선택적 초상화 아이콘 모두에 적용됩니다."
L["Tracked buffs viewer"] = "추적 버프 표시기"
L["Tracks your selected harmful auras on this UnitFrame's unit. Boss frames use their own boss1 through boss5 unit token."] = "이 UnitFrame의 유닛에서 선택한 해로운 오라를 추적합니다. 우두머리 프레임은 boss1부터 boss5까지 자체 유닛 토큰을 사용합니다."
L["Turns Blizzard token filters on or off for this frame. The first change automatically creates frame-specific rules; migrated Shared rules remain Shared until edited."] = "이 프레임의 Blizzard 토큰 필터를 켜거나 끕니다. 처음 변경하면 프레임 전용 규칙이 자동으로 생성되며, 이전된 공유 규칙은 편집하기 전까지 공유 상태로 남습니다."
L["Unavailable cast fill"] = "사용 불가 시전 채우기"
L["Up (Single Column)"] = "위로 (단일 열)"
L["Use Player HP Text"] = "플레이어 생명력 텍스트 사용"
L["Use portrait position while portrait is off"] = "초상화가 꺼져 있을 때 초상화 위치 사용"
L["Used only when this HP bar is explicitly set to Orb. Follow Player Power inherits the Player power orb size instead."] = "이 생명력 바가 구슬로 명시적으로 설정된 경우에만 사용됩니다. 플레이어 자원 따르기는 대신 플레이어 자원의 구슬 크기를 상속합니다."
L["Uses Blizzard's 12.1 AuraButton stealable filter. It adds no MSUF aura scan, ticker, or OnUpdate."] = "Blizzard 12.1 AuraButton의 훔치기 가능 필터를 사용합니다. MSUF 오라 검사, 티커, OnUpdate를 추가하지 않습니다."
L["Uses Player HP text settings and copies already-rendered Player HP text when it is current. Local Text X/Y still belong to this bar."] = "플레이어 생명력 텍스트 설정을 사용하며, 이미 그려진 플레이어 생명력 텍스트가 최신이면 그대로 복사합니다. 지역 텍스트 X/Y는 여전히 이 바에 속합니다."
L["Uses the Class Resource width for detached Player power without making Class Resources own the Player power controls."] = "직업 자원이 플레이어 자원 설정을 가져가지 않으면서 분리된 플레이어 자원에 직업 자원의 너비를 사용합니다."
L["Utility cooldown viewer"] = "보조 재사용 대기시간 표시기"
L["Visible behind the filled HP amount. At 100% HP the fill covers the background; Outline 0 does not disable this texture."] = "채워진 생명력 뒤에 보입니다. 생명력이 100%일 때는 채우기가 배경을 덮으며, 외곽선 0으로도 이 텍스처는 꺼지지 않습니다."
L["Weapon Enchants Off"] = "무기 마법부여 끔"
L["Weapon Enchants On"] = "무기 마법부여 켬"
L["While the defensive bar or portrait icon is enabled, hides every enabled tracked defensive from the normal player Buffs lane. Disabled defensive entries remain visible there."] = "방어 바 또는 초상화 아이콘이 켜져 있는 동안, 활성화된 모든 추적 방어 효과를 플레이어의 일반 버프 줄에서 숨깁니다. 비활성 방어 항목은 그곳에 그대로 표시됩니다."
L["Whole frame"] = "프레임 전체"
L["Width Mode"] = "너비 방식"

-- Menu localization pass 2026-08-06 (part 3): FAQ answers and search keyword blobs that are concatenated in source.
L["Bar Background Tint Custom color in Dark Mode background backgrond backround bg backdrop opacity alpha"] = "바 배경 색조 어두운 모드 사용자 지정 색상 배경 바탕 bg 불투명도 알파 background backdrop"
L["Frame Basics Enable Load Conditions Transparency Range Fade player target focus pet gone missing invisible"] = "프레임 기본 활성화 불러오기 조건 투명도 거리 페이드 플레이어 대상 주시 대상 소환수 사라짐 보이지 않음"
L["Frame Basics Smooth fill Power Bar Smooth fill health animation power animation soft fill weiche Fuellung"] = "프레임 기본 부드러운 채우기 자원 바 부드러운 채우기 생명력 애니메이션 자원 애니메이션 smooth fill"
L["General Use MSUF group frames If this switch is off enable disable turn off hide raid party mythic"] = "일반 MSUF 공격대 프레임 사용 이 설정이 꺼져 있을 때 활성화 비활성화 끄기 숨기기 공격대 파티 신화"
L["Group Frames Layout Smooth health fill Health Text Power Bar Smooth fill party raid weiche Fuellung"] = "파티/공격대 프레임 레이아웃 생명력 부드러운 채우기 생명력 텍스트 자원 바 부드러운 채우기 파티 공격대 smooth fill"
L["Group Frames Layout Transparency opacity fade target in combat out of combat alpha whole frame bars HP backdrop HP fill HP track preserve HP color"] = "파티/공격대 프레임 레이아웃 투명도 불투명도 페이드 대상 전투 중 비전투 중 알파 프레임 전체 바 생명력 배경 생명력 채우기 생명력 트랙 생명력 색상 유지"
L["MSUF Edit Mode moves frames and supported castbars. Aura icon placement is controlled from each unit page > Auras or Group Frames > Auras."] = "MSUF 편집 모드는 프레임과 지원되는 시전 바를 이동합니다. 오라 아이콘의 위치는 각 유닛 페이지 > 오라 또는 파티/공격대 프레임 > 오라에서 설정합니다."
L["Miscellaneous misc global style language menu behavior startup notices tooltips blizzard frames minimap sounds"] = "기타 전역 스타일 언어 메뉴 동작 시작 알림 툴팁 Blizzard 프레임 미니맵 소리"
L["Name Shortening Use custom settings for this scope Overrides Party Raid group frame name truncation font override shared changes"] = "이름 단축 이 범위에 사용자 지정 설정 사용 재정의 파티 공격대 공격대 프레임 이름 자르기 글꼴 재정의 공유 변경"
L["Open Appearance > Auras for scope-aware cooldown text, stack text, swipe, and duration-bar styling. Timer colors remain under Colors > Auras."] = "외관 > 오라를 열어 범위별 재사용 대기시간 텍스트, 중첩 텍스트, 쓸어내기, 지속시간 바 스타일을 설정하십시오. 타이머 색상은 색상 > 오라에 그대로 있습니다."
L["Open Boss Frames > Auras > Debuffs. SpellID blacklist entries, Blizzard filters, placement, and preview live together there; styling remains under Appearance > Auras."] = "우두머리 프레임 > 오라 > 디버프를 여십시오. SpellID 블랙리스트 항목, Blizzard 필터, 배치, 미리보기가 그곳에 함께 있으며 스타일은 외관 > 오라에 남아 있습니다."
L["Open Global Style > Miscellaneous > Unitframe tooltips to control tooltip source, anchor, visibility mode, and modifier key for MSUF unit and group frames."] = "전역 스타일 > 기타 > 유닛 프레임 툴팁을 열어 MSUF 유닛 프레임과 공격대 프레임 툴팁의 출처, 기준점, 표시 모드, 보조키를 설정하십시오."
L["Open Global Style > Miscellaneous for language, menu behavior, startup notices, tooltips, Blizzard frames, minimap icon, and sounds."] = "전역 스타일 > 기타를 열어 언어, 메뉴 동작, 시작 알림, 툴팁, Blizzard 프레임, 미니맵 아이콘, 소리를 설정하십시오."
L["Open Group Frames > Layout > Range Fade. Affects chooses frame or HP fading, and the alpha sliders control out-of-range and offline opacity."] = "파티/공격대 프레임 > 레이아웃 > 거리 페이드를 여십시오. 적용 대상에서 프레임 또는 생명력 페이드를 선택하고, 알파 슬라이더로 사거리 밖과 오프라인 상태의 불투명도를 조절합니다."
L["Open Group Frames > Layout > Transparency. Opacity controls in-combat and out-of-combat alpha; Fade target chooses whole frame, bars, HP, or backdrop. Backdrop and Health layers set base color, HP fill, and HP track opacity."] = "파티/공격대 프레임 > 레이아웃 > 투명도를 여십시오. 불투명도는 전투 중과 비전투 중의 알파를 조절하며, 페이드 대상에서 프레임 전체, 바, 생명력, 배경 중 하나를 선택합니다. 배경과 생명력 레이어는 기본 색상, 생명력 채우기, 생명력 트랙의 불투명도를 설정합니다."
L["Open Group Frames > Layout for Smooth health fill. For group-frame power bars, open Group Frames > Layout > Resource Bar > Smooth fill."] = "생명력 부드러운 채우기는 파티/공격대 프레임 > 레이아웃에 있습니다. 공격대 프레임의 자원 바는 파티/공격대 프레임 > 레이아웃 > 리소스 바 > 부드러운 채우기에서 설정합니다."
L["Open Group Frames > Layout, choose Party, Raid, or Mythic at the top, then turn off Use MSUF group frames. Use If this switch is off to choose whether Blizzard frames show normally or both frame systems stay hidden."] = "파티/공격대 프레임 > 레이아웃을 열고 상단에서 파티, 공격대, 신화 중 하나를 선택한 다음 MSUF 공격대 프레임 사용을 끄십시오. 이 설정이 꺼져 있을 때 항목에서 Blizzard 프레임을 정상 표시할지, 두 프레임 시스템을 모두 숨길지 선택합니다."
L["Open Group Frames > Layout. Frame Basics and Sorting control player/self visibility and how player units are ordered in group frames."] = "파티/공격대 프레임 > 레이아웃을 여십시오. 프레임 기본과 정렬이 플레이어와 자신의 표시 여부, 그리고 공격대 프레임 내 플레이어 순서를 결정합니다."
L["Open Group Frames > Layout. Frame Basics/Layout controls frame width, height, spacing, columns, and growth; Frame Scaling controls scale behavior."] = "파티/공격대 프레임 > 레이아웃을 여십시오. 프레임 기본/레이아웃이 너비, 높이, 간격, 열, 성장 방향을 결정하고 프레임 스케일링이 크기 동작을 결정합니다."
L["Open Group Frames > Status & Indicators for status icons, role/leader/assist, ready check, focus glow, and other group-frame state indicators."] = "파티/공격대 프레임 > 상태 및 표시기를 열어 상태 아이콘, 역할/파티장/부공대장, 준비 확인, 주시 대상 광원 등 공격대 프레임의 상태 표시를 설정하십시오."
L["Open Player > Auras, then turn off Buffs for the player frame. Scope-aware text and cooldown styling remains under Appearance > Auras."] = "플레이어 > 오라를 열고 플레이어 프레임의 버프를 끄십시오. 범위별 텍스트와 재사용 대기시간 스타일은 외관 > 오라에 그대로 있습니다."
L["Open a unit page, then use Range Fade. It is available for Target, Target of Target, Focus, Focus Target, Pet, and Boss."] = "유닛 페이지를 연 다음 거리 페이드를 사용하십시오. 대상, 대상의 대상, 주시 대상, 주시 대상의 대상, 소환수, 우두머리에서 사용할 수 있습니다."
L["Open the affected UnitFrame > Auras for icon size, placement, and filters. Use Appearance > Auras for scope-aware text and cooldown styling."] = "해당 UnitFrame > 오라에서 아이콘 크기, 배치, 필터를 설정하십시오. 범위별 텍스트와 재사용 대기시간 스타일은 외관 > 오라를 사용하십시오."
L["Open the affected UnitFrame > Auras or Group Frames > Auras and reduce visible counts, timer text, or unnecessary native filter rules."] = "해당 UnitFrame > 오라 또는 파티/공격대 프레임 > 오라를 열고 표시 개수, 타이머 텍스트, 불필요한 기본 필터 규칙을 줄이십시오."
L["Open the affected UnitFrame > Auras, choose Buffs or Debuffs, then adjust filters, icon size, rows, caps, and spacing. Party/Raid settings are in Group Frames > Auras."] = "해당 UnitFrame > 오라를 열고 버프 또는 디버프를 선택한 다음 필터, 아이콘 크기, 행 수, 최대 개수, 간격을 조정하십시오. 파티/공격대 설정은 파티/공격대 프레임 > 오라에 있습니다."
L["Open the unit page > Auras or the aura Position Popup for unit-frame aura placement. Buff/debuff icons are configured as aura layout, not moved through MSUF Edit Mode."] = "유닛 프레임의 오라 배치는 유닛 페이지 > 오라 또는 오라 위치 팝업에서 설정하십시오. 버프/디버프 아이콘은 오라 레이아웃으로 설정하며 MSUF 편집 모드로 옮기지 않습니다."
L["Range Fade group frame range check raid range check party range check out of range alpha offline opacity affects frame HP"] = "거리 페이드 공격대 프레임 사거리 확인 공격대 사거리 확인 파티 사거리 확인 사거리 밖 알파 오프라인 불투명도 적용 대상 프레임 생명력"
L["Range Fade unit frame range check range checker distance check out of range range alpha distance fade target targettarget focus focustarget pet boss"] = "거리 페이드 유닛 프레임 사거리 확인 거리 확인 사거리 밖 사거리 알파 거리 페이드 대상 대상의 대상 주시 대상 주시 대상의 대상 소환수 우두머리"
L["Rounded Texture Rounded frame texture Unit frames Group frames Power bars Mouseover highlights rounded frames round corners"] = "둥근 텍스처 둥근 프레임 텍스처 유닛 프레임 공격대 프레임 자원 바 마우스 오버 강조 둥근 프레임 둥근 모서리"
L["Status icons Indicator Level Enabled Anchor X Offset Y Offset Size Layer level text level indicator show level player level target level"] = "상태 아이콘 표시기 레벨 활성화 붙일 위치 X 위치 값 Y 위치 값 크기 레이어 레벨 텍스트 레벨 표시 플레이어 레벨 대상 레벨"
L["Text anchor offset font size layer spacing split spacing overlaps bars portraits status icons"] = "텍스트 붙일 위치 위치 값 글꼴 크기 레이어 그리기 순서 간격 분할 간격 겹침 바 초상화 상태 아이콘"
L["Use Group Frames > Layout for frame size and spacing, Auras for Buff/Debuff placement, and Status & Indicators for fixed-position status icons."] = "프레임 크기와 간격은 파티/공격대 프레임 > 레이아웃, 버프/디버프 배치는 오라, 고정 위치 상태 아이콘은 상태 및 표시기를 사용하십시오."
L["Use Group Frames pages: Layout for size, growth, sorting, bars, and text; Auras for Buff/Debuff placement, and Status & Indicators for status icons."] = "파티/공격대 프레임 페이지를 사용하십시오. 레이아웃은 크기, 성장, 정렬, 바, 텍스트를, 오라는 버프/디버프 배치를, 상태 및 표시기는 상태 아이콘을 담당합니다."
L["Use the unit page for per-unit castbar toggles and Global Style > Castbar for shared textures, direction, text, and interrupt options."] = "유닛별 시전 바 설정은 유닛 페이지에서, 공유 텍스처, 방향, 텍스트, 차단 옵션은 전역 스타일 > 시전 바에서 설정하십시오."
L["Welcome to Class Resources!\n\nWould you like to automatically set up a\ndetached Class Bar positioned above your\nEssential Cooldowns?\n\nThis configures class resource visibility,\nanchoring, width matching and detached\nPlayer Power in one click.\n\nYou can always run this later via the\n|cff00ff00Quick Setup: Class Bar|r button below."] = "직업 자원에 오신 것을 환영합니다!\n\n필수 재사용 대기시간 위에 분리된\n직업 바를 자동으로 설정할까요?\n\n이 작업은 직업 자원 표시, 고정, 너비 맞춤,\n분리된 플레이어 자원을 한 번에 설정합니다.\n\n나중에 아래의 |cff00ff00빠른 설정: 직업 바|r\n버튼으로 언제든지 다시 실행할 수 있습니다."
L["External Edit Mode"] = "External Edit Mode"
L["Show Grid2 in MSUF Edit Mode"] = "Show Grid2 in MSUF Edit Mode"
L["Grid2 Edit Mode integration"] = "Grid2 Edit Mode integration"
L["On (default): MSUF Edit Mode can move the Grid2 layout and its active detached groups. Grid2 remains the owner of its layout and saved positions."] = "On (default): MSUF Edit Mode can move the Grid2 layout and its active detached groups. Grid2 remains the owner of its layout and saved positions."
L["Show Details! in MSUF Edit Mode"] = "Show Details! in MSUF Edit Mode"
L["Details! Edit Mode integration"] = "Details! Edit Mode integration"
L["On (default): MSUF Edit Mode can move every active Details! window. Windows snapped together by Details! move as one native group."] = "On (default): MSUF Edit Mode can move every active Details! window. Windows snapped together by Details! move as one native group."
L["Turn either switch off to remove only those external movers. The third-party addon and its settings are not modified."] = "Turn either switch off to remove only those external movers. The third-party addon and its settings are not modified."

-- Menu localization pass 2026-08-06 (part 4): format keys replacing runtime string concatenation.
L[" - %d matches"] = " - %d개 일치"
L["%d / %d predefined enabled"] = "사전 설정 %d / %d개 활성화"
L["%d blocked spells · click an entry to remove"] = "차단된 주문 %d개 · 항목을 클릭하면 제거됩니다"
L["%d predefined enabled · %d custom · click a custom entry to remove"] = "사전 설정 %d개 활성화 · 사용자 지정 %d개 · 사용자 지정 항목을 클릭하면 제거됩니다"
